	title 'SANE         Elems         GS ROM 2.0'*****************************************************************			   **	   SANE Elems		   **			   **********************************************************************************************************************************			   **	Copyright (C) 1985-1987	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   *****************************************************************;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File:  Elems/Main		            ;;; Driver file for building 65816 Elems	V0.0	            ;;; Status: First attempt		            ;;; Copyright Apple Computer, Inc., 1983-1986	            ;;; All Rights Reserved		            ;;;			            ;;; Written by C. Hausmann, 1983		            ;;;			            ;;; Modification History		            ;;;      21Mar86 CRL	    Revised for 65816	            ;;;			            ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	include 'elems.macros'	include '::sys.equs.asm';------------------------------------------;; Equates from procedure CLASS_NAN;;------------------------------------------FCINF	EQU $FE	; -2: infiniteFCZERO	EQU $FF	; -1: zeroFCNORM	EQU $00	;  0: normalFCDENORM	EQU $01	;  1: denormalNANTRIG	EQU 33	; Invalid argument to trig routine. NANLOG	EQU 36	; Invalid argument to log routine. NANPOWER	EQU 37	; Invalid argument to x^i or x^y routine. NANFINAN	EQU 38	; Invalid argument to financial function. FOLOG2X	EQU 2FOLOG21X	EQU 6FOEXP2X	EQU $AFOEXP1X	EQU $CFOEXP21X	EQU $E;=================================================;; Imports;	IMPORT Clayton;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY ANN01	ENTRY ANN02	ENTRY ANNALLLOG	ENTRY ANNDOIT	ENTRY ANNDOUT	ENTRY ANNM1	ENTRY ANNO	ENTRY ANNOK	ENTRY ANNRINF	ENTRY ANNROK	ENTRY ANNSRC	ENTRY ANNUITYTOP	ENTRY ANNXN	ENTRY ATANP	ENTRY ATANQ	ENTRY ATANTOP	ENTRY CALL_SANE	ENTRY CHECKOP	ENTRY CLASSIFY	ENTRY CLASSSRC2	ENTRY CMPGTM1	ENTRY CMPM1N	ENTRY CMPTOFIN	ENTRY CMPZERO	ENTRY COEFFS	ENTRY COMPOUNDTOP	ENTRY COSP	ENTRY COSQ	ENTRY COSTOP	ENTRY DOPROCENTRY	ENTRY DOSCALE	ENTRY DSTONLY	ENTRY ERRFINAN	ENTRY EXAPPROX	ENTRY EXP1FINITE	ENTRY EXP1R	ENTRY EXP1RDONE	ENTRY EXP1ROOT	ENTRY EXP1TOP	ENTRY EXP21P	ENTRY EXP21Q	ENTRY EXP21RNORM	ENTRY EXPEASY	ENTRY EXPHARD	ENTRY EXPNONZERO	ENTRY EXPR	ENTRY EXPROOT	ENTRY EXPTOP	ENTRY FINPWRI	ENTRY FINPWRY	ENTRY FPK0	ENTRY FPK1	ENTRY FPK2	ENTRY FPK3	ENTRY FPK34	ENTRY FPK78	ENTRY FPKARAND	ENTRY FPKATNCONS	ENTRY FPKE	ENTRY FPKFOURTH	ENTRY FPKHALF	ENTRY FPKINF	ENTRY FPKLOGE2	ENTRY FPKM0	ENTRY FPKM1	ENTRY FPKMAXINT	ENTRY FPKMINF	ENTRY FPKPI2	ENTRY FPKPI4	ENTRY FPKPRAND	ENTRY FPKSQRT2	ENTRY FPKSQRTHALF	ENTRY FPKX2	ENTRY FPKX2FX2	ENTRY F_MAXINT	ENTRY KLUGE10	ENTRY KLUGE12	ENTRY KLUGE13	ENTRY KLUGE17	ENTRY KLUGE2	ENTRY KLUGE3	ENTRY KLUGE36	ENTRY KLUGE4	ENTRY KLUGE40	ENTRY KLUGE42	ENTRY KLUGE44	ENTRY KLUGE6	ENTRY KLUGE61	ENTRY KLUGE62	ENTRY KLUGE63	ENTRY KLUGE64	ENTRY KLUGE67	ENTRY KLUGE68	ENTRY KLUGE7	ENTRY KLUGE8	ENTRY KLUGE90	ENTRY KLUGE91	ENTRY KLUGE92	ENTRY KLUGE93	ENTRY KLUGE97	ENTRY LAFINI	ENTRY LANONZERO	ENTRY LANORMAL	ENTRY LOG12R	ENTRY LOG1PLUSX	ENTRY LOG21P	ENTRY LOG21Q	ENTRY LOG2R	ENTRY LOGAPPROX	ENTRY LOGERROR	ENTRY LOGFINI	ENTRY LOGINFIN	ENTRY LOGO	ENTRY LOGTOP	ENTRY MAKESRC2	ENTRY NEGPWRY	ENTRY NONPWRY	ENTRY OPERAND	ENTRY POLYEVAL	ENTRY POVERQ	ENTRY PastPrivate	ENTRY RANDTOP	ENTRY RESULTDELIVERED	ENTRY SINP	ENTRY SINQ	ENTRY SINTOP	ENTRY SPLIT	ENTRY SPLIT2	ENTRY TANP	ENTRY TANQ	ENTRY TANTOP	ENTRY TRIGFINI	ENTRY TRIGREDUCTION	ENTRY VSMAXINT	ENTRY XKLPENTRY	ENTRY XKLPSKIP	ENTRY XPWRBIG	ENTRY XPWRITOP	ENTRY XPWRK	ENTRY XPWRKCLEAR	ENTRY XPWRKDIV	ENTRY XPWRKLOOP	ENTRY XPWRY	ENTRY XPWRYCOM	ENTRY XPWRYHARD	ENTRY XPWRYOK	ENTRY XPWRYTOP	ENTRY Z0S00	ENTRY ZPWRNEG	ENTRY Call_FP	ENTRY Call_El;                copy elems/equs.o;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File:  equS.o;; Global equs for building 65816 Elems	V0.0;; Status: First attempt;; Copyright Apple Computer, Inc., 1983-1986;; All Rights Reserved;;;; Written by C. Lewis, May 1986;;;; Modification History;;       12May86 CRL Update Zero Page Use to agree with FP816 changes.	             ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; NOTE HARD REFERENCES TO FP816 EQUS.;OrigDirect	equ 6	; from FP's equ tableOrigBank	equ 8	; from FP's equ tableSpace1	equ 98	; 16 bytes at FP's FrctA+10Space2	equ 124	; 16 bytes at FP's FrctB+10Space3	equ 150	; 96 bytes at FP's FrctC+10;FFMask	equ $FF;;; Equates used for setting up calls to the Engine.  See routine CALL_SANE; below.  NOTE: Portions of the code expect entries other than F_DEST to; be nonzero so branches work correctly.;F_DEST	equ 0F_SRC	equ 2F_SRC2	equ 4F_ISRC	equ 6F_I	equ 8F_J	equ 10F_W	equ 12F_X	equ 14F_Y	equ 16F_Z	equ 18F_LOG21P	equ 20F_LOG21Q	equ 22F_EXP21P	equ 24F_EXP21Q	equ 26F_FPK1	equ 28F_FPKM1	equ 30F_FPK2	equ 32F_FPK3	equ 34F_FPKMAXINT	equ 36F_FPKSQRT2	equ 38F_FPKHALF	equ 40F_FPKSQTHALF	equ 42F_FPKFOURTH	equ 44F_FPK34	equ 46F_FPK78	equ 48F_FPKPI2	equ 50F_FPKPI4	equ 52F_FPKE	equ 54F_FPKLOGE2	equ 56F_FPK0	equ 58F_FPKM0	equ 60F_FPKINF	equ 62F_FPKMINF	equ 64F_SINQ	equ 66F_SINP	equ 68F_COSQ	equ 70F_COSP	equ 72F_TANQ	equ 74F_TANP	equ 76F_ATANQ	equ 78F_ATANP	equ 80F_FPKX2	equ 82F_FPKX2FX2	equ 84F_FPKATNCONS	equ 86F_FPKARAND	equ 88F_FPKPRAND	equ 90F_EXCPTION	equ 92F_OLDENV	equ 94F_SAVE_ENV	equ 96F_ACCUM	equ 98	; Corresponds to V_TEMP;;; There are four logarithm functions:  LN(x), LOG2(x), LN(1+x), and LOG2(1+x).; They share much of the same code, but	are distinguished by two bits.; In the same way, EXP(x), EXP2(x), EXP(x)-1, EXP2(x)-1 share the same; startup code.;BTLOGBASE2	equ 1	; Set if either LOG2(x) or LOG2(1+x);	                   ; Set if either EXP2(x) or EXP2(x)-1BTLOG1PLUSX	equ 2	; Set if either LN (1+x) or LOG2(1+x);	                   ; Set if either EXP(x)-1 or EXP2(x)-1EXT_LEN	equ 9	; Length in bytes of extended valueEXT_SIZE	equ 10	; Size in bytes of extended value.;OP1ADRS	equ $00OP2ADRS	equ $80OP3ADRS	equ $C0;OPXPWRI	equ $08	; <0000 1000> - after ROR;; Storage for temporaries. DIRECT PAGE OFFSETS.;;OPCODE	equ Space1	; Index into jump tableNUM_ADDR	equ Space1+1;EXCPTION	equ Space1+2	; Exception (-4..1);OLD_ENV	equ Space1+4SAVE_ENV	equ Space1+6	; Ptr to saved user's environ;SRC_CLASS	equ Space1+8	; Source classSRC_SIGN	equ Space1+9SRC2_CLASS	equ Space1+$ASRC2_SIGN	equ Space1+$BCLASS_CODE	equ Space1+$CCLASS_SIGN	equ Space1+$DI_SRC	equ Space1+$E;		0 bytes free at end	of Space1OP0_ADDR	equ Space2OP1_ADDR	equ Space2+3;; Data area for extended parameters;DEST	equ Space2+6;		0 bytes free at end	of Space2SRC	equ Space3SRC2	equ SRC+$A;; Used to save zero	page addresses for destination and source.  This is; necessary because	these locations are	not guaranteed across calls to; the SANE engine.	[UNCHANGED FOR 816 CODE.   CRL];SAVE_DEST	equ SRC2+$ASAVE_SRC2	equ SAVE_DEST+3SAVE1_CLASS	equ SAVE_SRC2+3SAVE1_SIGN	equ SAVE1_CLASS+1SAVE2_CLASS	equ SAVE1_SIGN+1SAVE2_SIGN	equ SAVE2_CLASS+1;; Extended and integer temporaries;V_TEMP	equ SAVE2_SIGN+1	; V - only used to save extended;		       ;   value prior to recursionFPTRASH	equ V_TEMP+$A	; trashed by calls to FPI_TEMP	equ FPTRASH+5J_TEMP	equ I_TEMP+2W_TEMP	equ J_TEMP+2	; WX_TEMP	equ W_TEMP+$A	; XY_TEMP	equ X_TEMP+$A	; YZ_TEMP	equ Y_TEMP+$A	; Z;; Temporary variables - most often used	to pass addresses to various; routines.  A0_ADDR is also used in the front end and again at; resultdelivered to hold temporarily the 6 bytes of return	address; from the original	stack.;A0_ADDR	equ Z_TEMP+$A	; 3 bytesD0_TEMP	equ A0_ADDR+3	; 2 bytesD2_TEMP	equ D0_TEMP+2	; 2 bytes;		0 bytes free at end	of Space3;                  COPY           elems/EQUS.O           ; Elem equates;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File:  EQUS.o;; EQUs for building 65816 Elems V0.0;; Status: First attempt;; Copyright Apple Computer, Inc., 1983-1986;; All Rights Reserved;;;; Written by C. Hausmann, 1983;;;; Modification History;;      21Mar86 CRL	    Revised for 65816;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;FBINVALID	EQU 1FBUFLOW	EQU 2FBOFLOW	EQU 4FBDIVZER	EQU 8FBINEXACT	EQU $10FBIplusX	EQU $11;;-----------------------------------------------------------; Operation code masks.;-----------------------------------------------------------FOADD	EQU $00	; addFOSUB	EQU $02	; subtractFOMUL	EQU $04	; multiplyFODIV	EQU $06	; divideFOCMP	EQU $08	; compare, no exception from unorderedFOREM	EQU $0C	; remainderFOZ2X	EQU $0E	; convert to extendedFOX2Z	EQU $10	; convert from extendedFORTI	EQU $14	; round to integral	valueFOSCALB	EQU $18	; binary scaleFOLOGB	EQU $1A	; binary logFOCLASS	EQU $1C	; classify;FOSETENV	EQU $01	; set environmentFOGETENV	EQU $03	; get environmentFONEG	EQU $0D	; negateFOABS	EQU $0F	; absolute value; UNDEFINED    EQU	  $13FOSETXCP	EQU $15	; set exceptionFOPROCENTRY	EQU $17	; procedure-entryFOPROCEXIT	EQU $19	; procedure-exitFOTESTXCP	EQU $1B	; test exception; UNDEFINED    EQU	  $1D; UNDEFINED    EQU	  $1F;;-----------------------------------------------------------; Operand format masks.;-----------------------------------------------------------FFEXT	EQU $0	; extended -- 80-bit floatFFINT	EQU $4	; integer  -- 16-bit integer;;;-----------------------------------------------------------; Class and sign inquiries.;-----------------------------------------------------------;       ;-----------------------------------------------------------; NaN codes.  ;-----------------------------------------------------------;;-----------------------------------------------------------; Elementary function operation code masks.;-----------------------------------------------------------;;; END OF FILE;; Popping stack of parameters (start up), general routines such as Polyeval,; Negate, Scalbxx, and clean up at end (pushing of result onto stack);                  COPY           elems/ELEMCTRL.O.A;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File:  ElemCTRL.O.A		             ;;; For building 65816 Elems V0.0		             ;;; Status: First attempt		             ;;; Copyright Apple Computer, Inc., 1983-1986	             ;;; All Rights Reserved		             ;;;			             ;;; Written by C. Hausmann, 1983		             ;;;			             ;;; Modification History		             ;;;   Dec 7 1983 - Revised by C.A.Hausmann	             ;;;                Modified order of evaluation in TANGUTS to provide more;;;                accurate results.  Calculates X^3*[X^2 * P/Q] instead  ;;;                of [X^5] * [P/Q].		             ;;;                Changed TAN such that	TAN(+PI/2) = +INF and            ;;;		TAN(-PI/2) = -INF	             ;;;   Jan 11 1984 - Modified order of evaluation in SINGUTS to calculate  ;;;                 [ X * (X*X)] * [P/Q]	instead of X * [(X*X)(P/Q]       ;;;                 Fixed table bugs in SINQ and COSQ	             ;;;                 Fixed sign bug in TAN	             ;;;                 Fixed operand-trashing bug (if SRC=DEST)	in X^Y,      ;;;                 compound, and annuity	             ;;;			             ;;;   Apr 3 1985  - CRL  Clean up redundant code.	             ;;;	    Changes involve	writing much of the	common code  ;;;	    in the form of kluges and then JMP & JSR to them ;;;	    1-2        call_sane, call1_sane, calliv_sane    ;;;	    3          exp1done	             ;;;	    4          xpwryhard	             ;;;	    5          xpwry and cmptofin	             ;;;	    6          sintop and tantop	             ;;;	    8 & 40-51  MOVEIT	             ;;;	    10-12      common stuff in PolyLoop	             ;;;	    13         scalebxx and skipfirstscaleb          ;;;	    17         expr	and exp1r	             ;;;	    19-28 & 90's  calls to call_sane                 ;;;	    30 & 31    calls to call_elems & call1v_sane     ;;;	    60's       calls to call1_sane                   ;;;			             ;;;      21Mar86 CRL	    Revised for 65816	             ;;;			             ;;;       8Nov86 KLH	    Elems bug fixed	in classify	           ;;;			             ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;			             ;;	          Elementary Functions	             ;;			             ;;                 Compound Interest and	Present Value Functions          ;;			             ;;	         Trigonometry Functions	             ;;			             ;;			             ;;	          by Carol A. Hausmann	             ;;			             ;;			             ;;              From	Pascal code by David Hough and Colin McMaster        ;;              (elementary functions and compound interest and           ;;              present value functions)	and 68000 code by	             ;;              Jerome Coonen (elementary functions, compound interest    ;;              and present value functions, trigonometry functions)      ;;              and Pascal code by Kenton Hanson (trigonometry            ;;              functions)		             ;;			             ;;	  Copyright Apple Computer Inc.,  1984	             ;;			             ;;------------------------------------------------------------------------;;;; When ELEM6502 is entered the stack has the form:;     2 ret adrs  <	 opcode word  <  dst adrs  <  src adrs	<  scc2 adrs; with a second source address only in the case of the financial functions; Compound and Annuity.;; The temporaries which are set up in a	stack frame for the	MAC version; (ELEMS68K) are allocated in the data space for the ELEM6502 version,; and in the direct	page for the 816 version.;; The opword is defined as:;       0000 0000 NNNN NNN0;;; When raising extended to an integer power, do explicit multiplies when; the exponent is smaller than some threshold.  It's 255 for now.; When the exponent	exceeds this threshold, computation is done with; log and exp.  The	6502 version never looks directly for the value, 255.; It is only necessary to look at the high byte to see if a	number is; <= 255.;;SMALLEXP        .EQU            255;;ELEMS816	PROC EXPORT	JSL IncBusyFlg;	PHD	; save direct register, set up	TCD	;   for use of SANE	direct page	PLA	STA <OrigDirect	; note: same space as FP uses!!!	PHB	; save original data bank reg'r	PHB	PLA	STA <OrigBank	; note: same space as FP uses!!!	PHK	; now set data bank	register	PLB	;   to point to this rom bank	BRA PastPrivate;	EXPORT PrivateEntryPrivateEntry		;       	JSL IncBusyFlg	EXPORT PastPrivatePastPrivate		; 	PLA	STA <A0_ADDR+4	; pop 6 bytes of return address	PLA	STA <A0_ADDR+2	PLA	STA <A0_ADDR	LONGA OFF	LONGI OFF	SEP #$30	PLA	STA <OPCODE	; Function	PLA	CLC	ROR <OPCODE	; Set up index into	tables;		        ; ELEMSTAB (jump table) and;		        ; ADDR_TAB	LDX <OPCODE	LDA |ADDR_TAB,X	STA <NUM_ADDR	; Number of addresses to pop;; Fetch the Destination address - always;	POP4 <SAVE_DEST	; Dst adrs, another	adrs comingZ0SCE	COPY_EXTEND <SAVE_DEST,<DEST ; Save copy of extended	LDA <SRC_CLASS	; Possibly from previous;		        ; invokation	STA <SAVE1_CLASS	; Will be saved on the stack;		        ; later - make copy.	LDA <SRC_SIGN	STA <SAVE1_SIGN	LDA <SRC2_CLASS	STA <SAVE2_CLASS	LDA <SRC2_SIGN	STA <SAVE2_SIGN	LDA <NUM_ADDR	BMI Z0S00	; 2 or 3 addresses	JMP DSTONLY	; Only one address - so don't;		        ; fetch source;; Fetch the Source address - two,three-address case only;	EXPORT Z0S00Z0S00		; ; Copy src using save_src2	LDA <OPCODE	CMP #OPXPWRI	BEQ z1s01	; Special X^I case	POP4 <SAVE_SRC2	; Temp use until z1s01Z0S01	COPY_EXTEND <SAVE_SRC2,<SRC ; Again, make copy;; Classify the source, but NOT for special XPWRI case;	MOVE3 <SAVE_SRC2,<OP0_ADDR ; Classify src operand	JSR CLASSIFY	STX <SRC_CLASS	AND #$80	; show only sign bit	STA <SRC_SIGN	BRA z1s02;; Special copy required for XPWRI case.	 In this case, the integer itself; was one the stack.;	EXPORT Z1S01Z1S01		; 	POP2 <I_SRCZ1S02	LDA #OP3ADRS	; In one or two-address case,	AND <NUM_ADDR	; will be pretending there	EOR #OP3ADRS	; is a src2 by making a copy	BNE MAKESRC2	; of dest.;; Fetch Source2 address - three-address	case only;	POP4 <SAVE_SRC2Z1S03	COPY_EXTEND <SAVE_SRC2,<SRC2	JMP CLASSSRC2	; Classify source2ADDR_TAB	DC.B OP1ADRS	; LNX	DC.B OP1ADRS	; LOG2X	DC.B OP1ADRS	; LN1X	DC.B OP1ADRS	; LOG21X	DC.B OP1ADRS	; EXPX	DC.B OP1ADRS	; EXP2X	DC.B OP1ADRS	; EXPX  - 1	DC.B OP1ADRS	; EXP2X - 1	DC.B OP2ADRS	; XPWRI	DC.B OP2ADRS	; XPWRY	DC.B OP3ADRS	; COMPOUND	DC.B OP3ADRS	; ANNUITY	DC.B OP1ADRS	; ATANX	DC.B OP1ADRS	; SINX	DC.B OP1ADRS	; COSX	DC.B OP1ADRS	; TANX	DC.B OP1ADRS	; RANDOMX	ENDP;; Routine to classify the operands - A0_addr pts to the extended value.; The class code is	returned in X, the sign is returned in Y.;	EXPORT CLASSIFYCLASSIFY	PROC	LONGA ON	LONGI ON	REP #$30	LDX <OP0_ADDR	phd	;<3Nov86 klh>	phb	;<3Nov86 klh>	LDA <OP0_ADDR+2	;<3Nov86 klh>	pha	;<3Nov86 klh>	bra elemfix	;<3Nov86 klh>;	EXPORT CLASS_2CLASS_2		;       	PHD	; save settings of D and B	PHB	PEA 0	; push addr in Xelemfix	PHX	;<3Nov86 klh>	LDA #FOCLASS	; invoke class fcn in engine	JMP KLUGE2	LONGA OFF	LONGI OFF;	EXPORT DSTONLYDSTONLY		;       	LDA #FCNORM	; Even though no source exists;		        ; for this case, fake a non-NAN;		        ; Class code for easy handling;		        ; of NAN checks	STA <SRC_CLASS;; Pretend there is a Source2 address - one-two address case;	EXPORT MAKESRC2MAKESRC2		;       	LDX #EXT_SIZEZ2S99	LDA <DEST-1,X	STA <SRC2-1,X	DEX	BNE z2s99	MOVE3 <SAVE_DEST,<SAVE_SRC2;; Whether we faked source2 or popped it	off the stack, classify it!;	EXPORT CLASSSRC2CLASSSRC2		;       	MOVE3 <SAVE_SRC2,<OP0_ADDR	JSR CLASSIFY	STX <SRC2_CLASS	AND #$80	; show only sign bit	STA <SRC2_SIGN	;   and save	LONGA ON	LONGI ON	REP #$30	LDA <A0_ADDR	; put both return addresses	PHA	;   back on the stack	LDA <A0_ADDR+2	PHA	LDA <A0_ADDR+4	PHA	JSR DOPROCENTRY	LONGA OFF	LONGI OFF	PUSH3 <SAVE_DEST	; Address of result;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; DANGER - DANGER - DANGER;;   Environment was working strangely.	 In old source this	was;;   PUSH2     <OLD_ENV          with old_env never initialized.;;   The change to <save_env looks correct.  It records the	initial;;   user's environment so it can be restored at resultdelivered.;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	PUSH2 <SAVE_ENV	; User's environment	LDA <SAVE1_CLASS	; Copy of Source Class	PHA	LDA <SAVE1_SIGN	PHA	LDA <SAVE2_CLASS	; Copy of Source2 Class	PHA	LDA <SAVE2_SIGN	PHA;; Check for NANs, either SRC2_CLASS (dst/src2) or SRC_CLASS	(src) equal to 1; or 2.  If the src	is a NAN, there might be two NANs so let floating add; determine precedence, or propagate the one NAN.  If just the dst; (or possible src2) is a NAN, do a simple move, in order to touch; any signaling NAN	that may have appeared.;	LDA <SRC_CLASS	CMP #FCINF	BPL NOT2NANS; get here is SRC is a NAN	LDX #F_SRC2	JSR KLUGE8;		        ; Might be dst or src2	LDX #F_SRC	JSR KLUGE97	JMP NANEXITNOT2NANS	LDA <SRC2_CLASS	; Check src2 or dst	CMP #FCINF	BPL LIFTOFF	LDX #F_SRC2	; Src2 or dst addr	LDY #F_DEST	; Dst addr	LDA #FOZ2X	JSR CALL_SANENANEXIT	JMP RESULTDELIVERED;	EXPORT DOPROCENTRYDOPROCENTRY		;       ; called in	16-bit mode	LONGA ON	LONGI ON	PHD	; save settings of D and B	PHB	PEA 0	; push addr of save_env	CLC	TDC	ADC #<SAVE_ENV	PHA	LDA #FOPROCENTRY	; invoke procentry	JMP KLUGE2	LONGA OFF	LONGI OFF;; Fall through to here in typical case of no NANs.; SRC_CLASS and SRC2_CLASS (dst/src2 class) contain the class codes.; Jump to specific routine based on opword in OPCODE;LIFTOFF	LDA <OPCODE	ASL A	; Get index into table	TAY	LDA |ELEMSTAB+1,Y	; Get address from table and	PHA	; push onto stack	LDA |ELEMSTAB,Y	PHA	RTS	; This RTS causes a	jump to;		        ; the address in the table;		        ; plus 1.ELEMSTAB	DC.W LOGTOP-1	; LNX	DC.W LOGTOP-1	; LOG2X	DC.W LOGTOP-1	; LN1X	DC.W LOGTOP-1	; LOG21X	DC.W EXPTOP-1	; EXPX	DC.W EXPTOP-1	; EXP2X	DC.W EXP1TOP-1	; EXPX - 1	DC.W EXP1TOP-1	; EXP2X - 1	DC.W XPWRITOP-1	; XPWRI	DC.W XPWRYTOP-1	; XPWRY	DC.W COMPOUNDTOP-1	; COMPOUND	DC.W ANNUITYTOP-1	; ANNUITY	DC.W ATANTOP-1	; ATANX	DC.W SINTOP-1	; SINX	DC.W COSTOP-1	; COSX	DC.W TANTOP-1	; TANX	DC.W RANDTOP-1	; RANDOMX	ENDP;; END OF FILE;;                  COPY           elems/ELEMCTRL.O.B;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File:  ElemCtrl.o.b		             ;;; For building 65816 Elems V0.0		             ;;; Status: First attempt		             ;;; Copyright Apple Computer, Inc., 1983-1986	             ;;; All Rights Reserved		             ;;;			             ;;; Written by C. Hausmann, 1983		             ;;;			             ;;; Modification History:		             ;;;      24Mar86 CRL	    Rewritten for 65816	             ;;;      24Nov86 KLH	    Fixed Elems bug		             ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	EXPORT KLUGE19KLUGE19	PROC	LONGA OFF	LONGI OFF	LDX #F_X	EXPORT KLUGE20KLUGE20		;       	LDY #F_DEST	EXPORT KLUGE25KLUGE25		;       	LDA #FOMUL	BNE CALL_SANE	EXPORT KLUGE22KLUGE22		;       	LDX #F_W	EXPORT KLUGE21KLUGE21		;       	LDY #F_X	BNE KLUGE25	EXPORT KLUGE23KLUGE23		;       	LDX #F_FPKHALF	EXPORT KLUGE24KLUGE24		;       	LDY #F_W	BNE KLUGE25	EXPORT KLUGE26KLUGE26		;       	LDX #F_SRC	EXPORT KLUGE27KLUGE27		;       	LDY #F_ACCUM	BNE KLUGE25	EXPORT KLUGE99KLUGE99		;       	LDY #F_DEST	LDA #FOREM	BNE CALL_SANE	EXPORT KLUGE96KLUGE96		;       	LDX #F_FPK1	EXPORT KLUGE97KLUGE97		;       	LDY #F_DEST	EXPORT KLUGE98KLUGE98		;       	LDA #FOADD;; Routines to invoke a call to the Sane	Arithmetic. Two-argument calls only.;; Input: X reg : Index into table of source address;        Y reg : Index into table of dest address;        Accum : Function opcode;	EXPORT CALL_SANECALL_SANE		;       	STA <OP0_ADDR	; Save opcode index	LONGA ON	LONGI ON	REP #$30	PHD	; save settings of D and B	PHB	JSR CHECKOP	PHX	PHA	TYX	LDY #FFEXT	; always extended	EXPORT LATEKLUGELATEKLUGE		;       	JSR CHECKOP	PHX	PHA	SEP #$30	LONGA OFF	LONGI OFF	TYA	EXPORT KLUGE1KLUGE1		;       	PHA	LDA <OP0_ADDR	EXPORT KLUGE2KLUGE2		;       	PHA	; Push opcode	CallFp	SEP #$30	; back to 8-bit mode        	LONGA OFF	LONGI OFF	PHP	; protect returns in status	PLA	;   by holding status in A	PLB	; restore D and DBR	PLD	;   (trashing n and	z bits)	PHA	; and restore status register	PLP	RTS;; Routines to invoke a call to the Sane	Arithmetic. Two-argument calls only.;; Input: X reg : Index into table of source address;        Y reg : Index into table of dest address;        Accum : Function opcode;	EXPORT CALLI_SANECALLI_SANE		;       	STA <OP0_ADDR	; Save opcode index	LONGA ON	LONGI ON	REP #$30	PHD	; save settings of D and B	PHB	JSR CHECKOP	PHX	PHA	TYX	LDY #FFINT	; always integer	BRA LATEKLUGE;; Routines to invoke a call to the Sane	Arithmetic. One-argument only.;; Input: X reg : Index into table of dest address;        Y reg : Function opcode;	EXPORT CALL1_SANECALL1_SANE		;       	LONGA ON	LONGI ON	REP #$30	PHD	; save settings of D and B	PHB	JSR CHECKOP	PHX	PHA	SEP #$30	LONGA OFF	LONGI OFF	LDA #FFEXT	; Always extended	PHA	TYA	; Opcode	BNE KLUGE2;; Routines to invoke a call to the Sane	Arithmetic. One integer value arg.;; Input: Y reg : Index into table of dest address;        X reg : Function opcode;	EXPORT CALL1V_SANECALL1V_SANE		;       	STZ <OP0_ADDR+2	; address below in bank 0	LONGA ON	LONGI ON	REP #$30	PHD	; save settings of D and B	PHB	CLC	TDC	ADC OPERAND,Y	; an address on direct page	STA <OP0_ADDR	LDA [<OP0_ADDR]	;   contents of that address	PHA	SEP #$30	LONGA OFF	LONGI OFF	LDA #FFINT	; Always integer	PHA	TXA	; Opcode	JMP KLUGE2;; Routine to call SANE.  Zero argument only.;; Input: X reg : Index into table of dest address;        Y reg : Function opcode;	EXPORT CALL0_SANECALL0_SANE		;       	LONGA ON	LONGI ON	PHD	; save settings of D and B	PHB	TYA	BRA KLUGE2	LONGA OFF	LONGI OFF;	              ; Routines to invoke a call to the Elems. One-argument only.;; Input: X reg : Index into table of dest address;        Y reg : Function opcode;	EXPORT KLUGE30KLUGE30		;       	LDX #F_ACCUM	EXPORT CALL_ELEMSCALL_ELEMS		;       	LONGA ON	LONGI ON	REP #$30	PHD	; save settings of D and B	PHB	JSR CHECKOP	PHX	PHA	PHY	; opcode in Y, hi byte xx	SEP #$30	CallEl	PLB	; restore D and DBR	PLD	SEP #$30	LONGA OFF	LONGI OFF	RTS;; Checkop computes a 4 byte address from a single byte index;;           Input:	X = offset into table of addresses at OPERAND;           Output:	A = low word of required 4 byte address;	X =  hi word of required 4 byte address;; The routine must distinguish between ROM addresses and direct page addresses.;           Direct page addresses are:	0-word,  D + value at OPERAND,X.;           ROM addresses are:	0-byte,  DBR-byte,	value at OPERAND,X.;	EXPORT CHECKOPCHECKOP		;       	PHP	; save operating state	SEP #$30	CPX #F_LOG21P	; is x between 0 and 18?	BCC AddD	;   if so, it's in direct page	CPX #F_EXCPTION	; is x between 92 and 98?	BCS AddD	;   if so, it's in direct page	LDA #0	; ADDRESS IN ROM	PHA	; 4th byte of address is 0	REP #$30	LONGA ON	LONGI ON	LDA OPERAND,X	; collect low word of address	PHB	; 3rd byte of address is DBR	PLX	; pull hi word of address: 0,DBR	BRA ENDCHECKAddD	REP #$30	; ADDRESS IN DIRECT	PAGE	CLC	;   and compute direct page addr	TDC	ADC OPERAND,X	; address low = D +	offset	LDX #0	; address hi is 0ENDCHECK	PLP	; restore operating	state	RTS	ENDP;; Utility to evaluate a polynomial using Horner's recurrence.; Input:  Parameters are passed via zero-page registers 10-14;         A0_ADDR	pts to result field	(preserved);         OP1_ADDR	pts to coefficient table (advanced beyond table).;         A2_ADDR	pts to function value (preserved).; Uses:   X,Y registers; All operands are extended.  The polynomial table consists	of; a leading word N,	a positive integer giving the degree of	the; polynomial, and then (N+1) extended coefficients, starting with; that of the leading term.; RESULT  <-- C0  initially.; RESULT  <-- (RESULT * X) + CJ   for J	= 1 to DEGREE; Since OP1_ADDR is	advanced beyond the	end of the given coefficient table,; POLYEVAL may be used sucessively with	consecutive tables,	after setting; OP1_ADDR just once.;	EXPORT KLUGE35KLUGE35	PROC	; 12MAY86 uncalled????	LONGA OFF	LONGI OFF;               LDA	            OPERAND+1,Y;               STA	            <OP1_ADDR+1;               LDA	            OPERAND,Y;               STA	            <OP1_ADDR;               RTS	EXPORT KLUGE29KLUGE29		;       	LDA #F_X	BNE POLYEVAL	EXPORT KLUGE32KLUGE32		;       	LDX #F_X	LDA #F_Y	BNE POLYEVAL	EXPORT KLUGE33KLUGE33		;       	LDA #F_W	LDY <I_TEMP; Evaluates a polynomial in T by Horner's recursion.  Each loop uses 3 variables:;;               VARIABLE        INDEX REG       POINTER	    LOCATION;               ------------------------------------------------;               T	            A	        OP0_ADDR	    direct page;               Coeff           Y	        OP1_ADDR	    ROM;               Result          X	        A0_ADDR	    direct page	EXPORT POLYEVALPOLYEVAL		;       	LONGA ON	LONGI ON	REP #$30	AND #$00FF	; KLH 24Nov86	STA <OP0_ADDR	; save index of result	CLC	TDC	ADC OPERAND,X	; copy result address to A0	STA <A0_ADDR	LDA OPERAND,Y	; copy address of coeffs to op1	STA <OP1_ADDR	LDX <OP0_ADDR	; retrieve result index	CLC	TDC	ADC OPERAND,X	; copy address of argument X	STA <OP0_ADDR	SEP #$30	LONGA OFF	LONGI OFF	LDY #0	LDA (<OP1_ADDR),Y	; copy #coeffs to D0	STA <D0_TEMP	LDX #$2	; point to 1st coeff,	LDY #FOZ2X	;   copy it to result	JSR KLUGE10	EXPORT POLYLOOPPOLYLOOP		;       	LDY #FOMUL	JSR KLUGE12	LDX #EXT_SIZE	LDY #FOADD	JSR KLUGE10	DEC <D0_TEMP	BNE POLYLOOP	RTS	EXPORT KLUGE10KLUGE10		;       	CLC	TXA	ADC <OP1_ADDR	; 3rd byte of OP1 =	DBR	STA <OP1_ADDR	LDA <OP1_ADDR+1	ADC #$0	STA <OP1_ADDR+1	LDX #$0	; push 4 byte address of OP1	PHD	; save D and B before fp call	PHB	PHX	PHB	; OP1 pts to a constant in ROM	PHA	LDA <OP1_ADDR	EXPORT KLUGE11KLUGE11		;       	PHA	PEA 0	; push zero page address of A0	LDA <A0_ADDR+1	PHA	LDA <A0_ADDR	PHA	LDA #FFEXT	; push opword and call engine	PHA	TYA	JMP KLUGE2	EXPORT KLUGE12KLUGE12		;       	PHD	; save B and D before fp call	PHB	PEA 0	; push zero page address of op0	LDA <OP0_ADDR+1	PHA	LDA <OP0_ADDR	BRA KLUGE11;; Clear the exception flag by getting, tweaking, and restoring the; environment word.; Input:  EXCPTION = exception bit index; Uses:   J_ADDR;	EXPORT CLEARUFLOWCLEARUFLOW		;       	LDA #FBUFLOW	BNE CLEARX2	EXPORT CLEAROFLOWCLEAROFLOW		;       	LDA #FBOFLOW	BNE CLEARX2	EXPORT CLEARINVALIDCLEARINVALID		;       	LDA #FBINVALID	BNE CLEARX2	EXPORT CLRINEXACTCLRINEXACT		;       	LDA #FBINEXACTCLEARX2	STA <EXCPTION	EXPORT CLEARXCLEARX		;       	LONGA ON	LONGI ON	REP #$30	; 16 bit mode	LDY #FOGETENV	; Get environment word -	JSR CALL0_SANE	;   returned in X and Y	LONGA OFF	LONGI OFF	STX <J_TEMP	STY <J_TEMP+1	; exceptions in hi byte	LDA <EXCPTION	EOR #FFMask	; Complement excption	AND <J_TEMP+1	; Turn off excption	STA <J_TEMP+1	PHD	; save B and D before fp call	PHB	LDA <J_TEMP+1	; Try this..	PHA	LDA <J_TEMP	PHA	PHA	LDA #FOSETENV	JMP KLUGE2;; Utility to force a flag.; Uses: EXCPTION.;	EXPORT FORCEOFLOWFORCEOFLOW		;       	LDA #FBOFLOW	BNE FORCEX2	EXPORT FORCEUFLOWFORCEUFLOW		;       	LDA #FBUFLOW	BNE FORCEX2	EXPORT FORCEDIVZERFORCEDIVZER		;       	LDA #FBDIVZER	BNE FORCEX2	EXPORT FORCEINVALIDFORCEINVALID		;       	LDA #FBINVALID	BNE FORCEX2	EXPORT FORCEINEXACTFORCEINEXACT		;       	LDA #FBINEXACTFORCEX2	STA <EXCPTION	EXPORT FORCEXFORCEX		;       	LDX #FOSETXCP	BNE TESTX1;; Utility to test an exception flag.; Output: Z flag in	Status register is set if exception flag is off, Z is; 0 if flag is on.;	EXPORT TESTUFLOWTESTUFLOW		;       	LDA #FBUFLOW	BNE TESTX2	EXPORT TESTOFLOWTESTOFLOW		;       	LDA #FBOFLOW	BNE TESTX2	EXPORT TESTDIVZERTESTDIVZER		;       	LDA #FBDIVZER	BNE TESTX2	EXPORT TESTINVALIDTESTINVALID		;       	LDA #FBINVALID	BNE TESTX2	EXPORT TESTINEXACTTESTINEXACT		;       	LDA #FBINEXACTTESTX2	STA <EXCPTION	EXPORT TESTXTESTX		;       	LDX #FOTESTXCPTESTX1	LDA #$0	STA <EXCPTION+1	EXPORT KLUGE31KLUGE31		;       	LDY #F_EXCPTION	JMP CALL1V_SANE	; Clears Z flag if exception;;               This routine copies one	extended value to another.;               x -> y where y is always on direct page, but x can;               be in direct or rom.  x	is determined by the offset;               in the X register.  For	x = 0..18 or 92..98, the;               address is direct page,	otherwise rom.;	EXPORT KLUGE8KLUGE8		;       	LDY #F_DEST	EXPORT MOVEITMOVEIT		;       	JSR CHECKOP	; return address for x in X & A	STA <OP0_ADDR	XBA	STA <OP0_ADDR+1	STX OP0_ADDR+2	STZ <OP1_ADDR+2	LONGA ON	LONGI ON	REP #$30	CLC	TDC	ADC OPERAND,Y	STA <OP1_ADDR	LDY #$8Z1S04	LDA [<OP0_ADDR],Y	STA [<OP1_ADDR],Y	DEY	DEY	BPL z1s04	SEP #$30	LONGI OFF	LONGA OFF	RTS;; This routine negates an integer.  Integer must be in J_TEMP;	EXPORT NEGATENEGATE		;       	SEC	LDA #$0	SBC <J_TEMP	STA <J_TEMP	LDA #$0	SBC <J_TEMP+1	STA <J_TEMP+1	RTS	ENDP;; END OF FILE;; Log;                  COPY           elems/ELEM1.O;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File:  Elem1.o			             ;;; For building 65816 Elems V0.0		             ;;; Status: First attempt		             ;;; Copyright Apple Computer, Inc., 1983-1986	             ;;; All Rights Reserved		             ;;;			             ;;; Written by C. Hausmann, 1983		             ;;;			             ;;; Modification History:		             ;;;      24Mar86 CRL	    Rewritten for 65816	             ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; Floating scalb function computes (A0)	 <--  (A0) * 2^(A1); Because of the 15-bit exponent range,	just two invocations; of FSCALBX are required if an over/underflow is to be simulated.; (A0) and (A1) are	passed via zero-page registers; A0_ADDR, A1_ADDR are not modified.; Uses:  J_TEMP,;        Y_ADDR (pointer to extended temporary);	EXPORT SCALBXXSCALBXX	PROC	LONGA OFF	LONGI OFF	MOVE2 F_MAXINT,<J_TEMPZ2S000	COPY_EXTEND <OP1_ADDR,<Y_TEMP	LDX #F_Y	JSR KLUGE68;; if (SP) is larger	than MAXINT then do	one step of scaling	by MAXINT.;	JSR VSMAXINT	FBGE Z2S00;; Must diminish (Y)	by FPKMAXINT.;	LDX #F_FPKMAXINT	LDY #F_Y	JSR KLUGE91	JSR KLUGE13;; If (SP) exceeds FPKMAXINT at this step, just force signed	FPKMAXINT;Z2S00	JSR VSMAXINT	; (SP) vs. FPKMAXINT	FBGE z2s01	LDX #F_FPKMAXINT	JMP z2s03Z2S01	LDX #F_YZ2S03	LDY #F_J	; Index of addrss of MAXINT or;		        ; -MAXINT	LDA #FOX2Z	; Convert reduced value to;		        ; integer data type	JSR CALLI_SANE	JMP KLUGE13	ENDP;; Scale (A0) by integer in JTEMP;	EXPORT SCALEINTSCALEINT	PROC	LONGA OFF	LONGI OFF	PHD	; save settings of D and B	PHB	PUSH2 <J_TEMP	; DANGER!! we are pushing;		        ; a value -- not an address;		        ; here!	PUSH4 <A0_ADDR	LDA #0	PHA	LDA #FOSCALB	JMP KLUGE2	EXPORT KLUGE13KLUGE13		;       	LONGA ON	LONGI ON	REP #$30	LDX <OP1_ADDR	JSR CLASS_2	; Check operand sign	LONGA OFF	LONGI OFF	FBPLUS z3s01	JSR NEGATE	; Negate MAXINTZ3S01	JMP SCALEINT	; Scale (A0) by MAXINT or;		        ; -MAXINT;; Compare extended value with FPKMAXINT;	EXPORT VSMAXINTVSMAXINT		;       	LDX #F_FPKMAXINT	LDY #F_Y	EXPORT KLUGE28KLUGE28		;       	LDA #FOCMP	JMP CALL_SANE	ENDP;; Trailing stubs to	deal with special values to be delivered.;	EXPORT POSTUFFPOSTUFF	PROC	LONGA OFF	LONGI OFF	LDX #F_FPK0	BNE KLUGE7	EXPORT MOSTUFFMOSTUFF		;       	LDX #F_FPKM0	BNE KLUGE7	EXPORT P1STUFFP1STUFF		;       	LDX #F_FPK1	BNE KLUGE7	EXPORT M1STUFFM1STUFF		;       	LDX #F_FPKM1	BNE KLUGE7	EXPORT DIVPOSTUFFDIVPOSTUFF		;       	JSR FORCEDIVZER	EXPORT PINFSTUFFPINFSTUFF		;       	LDX #F_FPKINF	BNE KLUGE7	EXPORT DIVMOSTUFFDIVMOSTUFF		;       	JSR FORCEDIVZER	EXPORT MINFSTUFFMINFSTUFF		;       	LDX #F_FPKMINF	EXPORT KLUGE7KLUGE7		;       	JSR KLUGE8	JMP RESULTDELIVERED	ENDP;; Fabricate a silent NAN, set Invalid, and deliver to destination.;	EXPORT ERRORNANERRORNAN	PROC	LONGA OFF	LONGI OFF	LDA <CLASS_SIGN	; 0=positive,1=negative	BNE z4s099	LDA #$7F	JMP z4s088Z4S099	LDA #FFMaskZ4S088	STA <DEST+9	LDA #FFMask	STA <DEST+8	LDA #$40	STA <DEST+7	LDA <CLASS_CODE	STA <DEST+6	LDA #$0	LDX #$5	; Byte countZ4S09	STA <DEST,X	DEX	BPL z4s09	JSR FORCEINVALID;; Finally, a result	has been placed in DEST.  Restore the environment,; signalling any required exceptions, restore the registers.;	EXPORT RESULTDELIVEREDRESULTDELIVERED		;       	PLA	STA <SRC2_SIGN	PLA	STA <SRC2_CLASS	PLA	STA <SRC_SIGN	PLA	STA <SRC_CLASS	POP2 <OLD_ENV	POP3 <SAVE_DEST	LDY #EXT_LEN	; return result	PHX	TYXZ5S10	LDA <DEST,X	STA [<SAVE_DEST],Y	DEY	DEX	BPL z5s10	PLX;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; Note sleazy ending.  Pick up return addresses from stack,;;    then push original saved environment, push procexit opcode,;;    and invoke PROCEXIT:  not by JSR,	but instead by pushing;;    original return addresses from stack at entry to elems call;;    and doing a jump to the FP code.;; In this way, all	elems calls go out through the FP back end.;;    This ought to	make SANE look like	a one entry, one exit;;    piece of code.  Halt mechanism writers may even like it!;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	LONGA ON	LONGI ON	REP #$30	PLA	STA A0_ADDR	PLA	STA A0_ADDR+2	PLA	STA A0_ADDR+4;	LDA <OLD_ENV	PHA	PEA FOPROCEXIT;	LDA A0_ADDR+4	PHA	LDA A0_ADDR+2	PHA	LDA A0_ADDR	PHA;	JSL DecBusyFlg	; TEMPORARILY ZERO!!!!	JMP Clayton;; Two short routines used to call FP and Elems from inside the code itself.;   Each fakes up 2	return addresses so	dispatcher can be avoided.;	EXPORT Call_ElCall_El		;       	JSL PrivateEntry	RTL	EXPORT Call_FpCall_Fp		;       	JSL Clayton	RTL	ENDP;; Logarithm functions; All four functions  LN(x), LOG2(x), LN(1+x), and LOG2(1+X); are launched by common error-checking	code.  In the usual	case; that arithmetic is required, the computation is cast in the form; log2(1+z).  The only difference between LN and LOG2 is that the; former requires a	final multiplication by LN(2).;; The four functions are distinguished by the BTLOGBASE2 and; BDLOG1PLUSX bits as described in the EQU section above.;; Since the only operand is the destination, the relevant class code; (already diminished by FCINF in the NAN check) is in SRC2_CLASS.; SRC2_CLASS corresponds to D1.B in Jerome's version of the Elems.;; 6502 vs 68000 version naming conventions:;; OPCODE       <-->	    D3.W; DEST         <-->	    (A4)    { equivalent also to SRC2_PTR }; SRC2_CLASS   <-->	    D1.B; SRC2_SIGN    <-->	    D1.W;	EXPORT LOGTOPLOGTOP	PROC	LONGA OFF	LONGI OFF	LDA <SRC2_CLASS	CMP #FCINF	BEQ LOGINFIN;; Finite case	LDA #BTLOG1PLUSX	BIT <OPCODE	BNE LOG1PLUSX	LDA <SRC2_CLASS	BMI LOGO;		        ; -INF, with divide by 0	LDA <SRC2_SIGN	; Check sign;		        ; 0=positive, 80 (hex)=negative	BMI LOGERROR	JMP LOG2R;; case - Log for infinite value;	EXPORT LOGINFINLOGINFIN		;       	LDA <SRC2_SIGN	; 0-pos, 1-neg	BNE LOGERROR	JMP PINFSTUFF	; Log(+INF) is +INF	EXPORT LOGERRORLOGERROR		;       	LDA <SRC2_SIGN	STA <CLASS_SIGN	LDA #NANLOG	; Error code	STA <CLASS_CODE	JMP ERRORNAN	; Log (-INF) is an error	EXPORT LOG1PLUSXLOG1PLUSX		;       	LDA <SRC2_CLASS	BPL z6s06;		        ; is 0 if operand is 0	JMP RESULTDELIVERED;		        ; LOG(+-0) is +-0Z6S06	LDX #F_FPKM1	LDY #F_DEST	JSR KLUGE28	FBUGT LOGERROR	; if -1 > operand, then error	FBLT LOG12R	; Find LOG (1+x);		        ; Fall through when = -1	EXPORT LOGOLOGO		;       	JMP DIVMOSTUFF	; End of special cases;; Compute LOG2(1 + T) for some positive, finite T.; if 1 + T falls outside the range SQRT(1/2) to SQRT(2) then; just go to the code for LOG2(S) below.  Else use LOGAPPROX; on T itself, IGNORING the sum 1 + T.;	EXPORT LOG12RLOG12R		;       ;; First compute 1 +	T, saving the input	T in cell W.;	JSR KLUGE42	JSR KLUGE96	; Dest := 1 + T;; Now compare with bounds SQRT(1/2) and	SQRT(2).;	LDX #F_DEST	LDY #F_FPKSQTHALF	JSR KLUGE28	FBULE LOG2R	LDX #F_FPKSQRT2	LDY #F_DEST	JSR KLUGE28	FBLE LOG2R;; Input T is within	the required range so restore input value and; just LOGAPPROX and finish up.;	JSR KLUGE40	JSR LOGAPPROX	JMP LOGFINI	EXPORT KLUGE40KLUGE40		;       	LDX #F_W	JMP KLUGE8	EXPORT KLUGE42KLUGE42		;       	LDX #F_DEST	EXPORT KLUGE41KLUGE41		;       	LDY #F_W	JMP MOVEIT	EXPORT KLUGE49KLUGE49		;       	LDX #F_DEST	EXPORT KLUGE50KLUGE50		;       	LDY #F_X	JMP MOVEIT	EXPORT KLUGE51KLUGE51		;       	LDX #F_DEST	EXPORT KLUGE52KLUGE52		;       	LDY #F_Y	JMP MOVEIT;; Compute LOG2(T) for some positive, finite T.; Represent T as 2^L * Q for SQRT (1/2)	<= Q <= SQRT(2).; Then LOG2(T) is L	+ LOG2(Q).; LOG2(Q) for that restricted range is computed at LOGAPPROX below.;	EXPORT LOG2RLOG2R		;       ;; Compute LOGB(T), i.e., L, in W.;	JSR KLUGE42	LDX #F_W	LDY #FOLOGB	JSR CALL1_SANE;; Then scale T down	to range 1 to 2.  Use custom scale function with a; floating number as the second argument.;	LDX #F_W	JSR KLUGE67	; -L in W	JSR KLUGE36	LDX #F_W	JSR KLUGE67	; Back to L in W;; If scaled value exceeds SQRT(2), then	halve T and increment L.;	LDX #F_DEST	LDY #F_FPKSQRT2	JSR KLUGE28	FBULE z7s01	LDX #F_FPK1	LDY #F_W	JSR KLUGE98	; Increment L by 1	JSR DOSCALE	; scale by -1 = T/2;; Now must subtract	1 from DEST in order to use LOGAPPROX,; which approximates LOG2(1 + S).;Z7S01	LDX #F_FPK1	JSR KLUGE90	JSR LOGAPPROX;; Add L in.  Exit via check to see whether to multiply by LN(2).;	LDX #F_W	JSR KLUGE97; Finish up with a multiply by LN(2) if	a natural log was requested.;	EXPORT LOGFINILOGFINI		;       	LDA #BTLOGBASE2	BIT <OPCODE	BNE z8s01	LDX #F_FPKLOGE2	JSR KLUGE20Z8S01	JMP RESULTDELIVERED;	EXPORT DOSCALEDOSCALE		;       	LONGA ON	LONGI ON	REP #$30	PHD	; save settings of D and B	PHB	LDA #$FFFF	; push -1 scale factor	PHA	PEA 0	; push dest address	CLC	TDC	ADC #<DEST	PHA	LDA #FOSCALB	; full word	JMP KLUGE2	LONGA OFF	LONGI OFF;; Compute LOG2(1+S)	for S between SQRT(1/2) and SQRT(2).; Assume all special cases have been filtered out and that; number DEST is indeed within range.; Let R := S / (2 +	S).; Then LOGAPPROX :=	R * P(R*R) / Q(R*R),; where the coefficients are taken from	LOG21P and LOG21Q.;; Leave cell W alone, for use by LOG2R.; Use cell Y_TEMP for R, X_TEMP for R*R.; Use DEST for R * P(R*R);  then Y_TEMP	for Q(R*R).; Registers A0TEMP-A2TEMP are used by the POLYEVAL.;; To avoid spurious	inexact, filter out	0.; To keep accuracy,	filter out denorms.	EXPORT LOGAPPROXLOGAPPROX		;       	JSR KLUGE61	CPX #FCZERO	; Zero?	BNE LANONZERO	; Quit exit if zero	RTS	EXPORT LANONZEROLANONZERO		;       	CPX #FCNORM	BEQ LANORMAL	; 0-norm, 1-denorm;; Since log2(1 + tiny) = ln (1 + tiny)/	ln(2) and ln (1 + tiny) is tiny + ...; just divide denorm by ln(2) and return.  Share exit code with main; computation.;	LDX #F_FPKLOGE2	JMP LAFINI	EXPORT LANORMALLANORMAL		;       	JSR KLUGE49	LDX #F_FPK2	JSR KLUGE97	LDX #F_DEST	LDY #F_X	JSR KLUGE93	LDX #F_X	; Y := R	LDY #F_Y	JSR MOVEIT	LDX #F_X	JSR KLUGE21;; Evaluate P (R*R) into DEST;	LDX #F_DEST	; Result into DEST	LDY #F_LOG21P	; Coefficients of P	JSR KLUGE29;; Evaluate R * P (R*R) into DEST;	LDX #F_Y	; R	JSR KLUGE20;; Evaluate Q (R*R) into Y;	LDX #F_Y	; Result into Y	LDY #F_LOG21Q	; Coefficients of Q	JSR KLUGE29;; Be sure inexact is set and clear all underflows up to the	last step; Finally, divide (R * (P (R*R)) in DEST by Q (R*R) in Y;	JSR CLEARUFLOW	LDX #F_Y	; Q (R * R)	EXPORT LAFINILAFINI		;       	JSR KLUGE92	JMP FORCEINEXACT	ENDP;; END OF FILE;; Exp, X^I;                  COPY           elems/ELEM2.O;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File:  Elem2.o			             ;;; For building 65816 Elems V0.0		             ;;; Status: First attempt		             ;;; Copyright Apple Computer, Inc., 1983-1986	             ;;; All Rights Reserved		             ;;;			             ;;; Written by C. Hausmann, 1983		             ;;;			             ;;; Modification History:		             ;;;      24Mar86 CRL	    Rewritten for 65816	             ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; EXP(x) and EXP2(x) share the same exception code.  To compute; numerical results, express resultas 2^K * ((2^frac - 1) +	1),; and use EXAPPROX to figure (2^frac - 1).;	EXPORT EXPTOPEXPTOP	PROC	LONGA OFF	LONGI OFF	LDA <SRC2_CLASS	BPL EXPNONZERO	; Handle positive non-zero case	CMP #FCZERO	BEQ z1s05	; Handle zero case	LDA <SRC2_SIGN	; 0=positive, 80 (hex) =negative	BMI z1s01	JMP RESULTDELIVERED	; Already have +INF	in DESTZ1S05	JMP P1STUFF	; EXP (+-0) is +1Z1S01	JMP POSTUFF	; EXP (-INF) is +0	EXPORT EXPNONZEROEXPNONZERO		;       	LDA #BTLOGBASE2	BIT <OPCODE	; Nonzero if EXP2X	BEQ EXPR;; 2^T is easy, for general T.; Set cell W to integer part of T.; Set T to fraction	part of itself.; User root computation to evaluate 2^T	- 1 with LOGAPPROX;; add 1 to T, and scale by W.;	EXPORT EXP2REXP2R		;       	JSR SPLIT2	JMP EXPROOT	; and exit...;; EXP(T) is just slightly more complicated than EXP2(T) above.; Let T = K * LN(2)	+ F; Then EXP(T) is 2^K + ((2^F/LN(2)) - 1) + 1).; So user EXP2ROOT with W set to K and T set to F/LN(2).; Find F with REM modulo LN(2); then subtract from T and divide by LN(2); to get K.	EXPORT EXPREXPR		;       	JSR SPLIT	JSR TESTOFLOW	BEQ EXPROOT	; This may change depending;		        ; on how FTESTXCP is handled	JSR KLUGE17	JSR FORCEUFLOW	JMP POSTUFF	EXPORT KLUGE17KLUGE17		;       	JSR FORCEINEXACT	; Either O/UFLOW	LDA <SRC2_SIGN	; 0=positive,80=negative	BMI z2s01	PLA	PLA	JMP PINFSTUFF	; Oflow to +INFZ2S01	JMP CLEAROFLOW;; This is the root of V^X where V is 2 or E.; Compute  ((2^T - 1) + 1) * 2 * W.  EXAPPROX gives the innermost; expression.  W is	presumed to be an integer, possibly huge.;	EXPORT EXPROOTEXPROOT		;       	JSR EXAPPROX	; DEST <-- 2^T - 1	JSR KLUGE3	JMP RESULTDELIVERED;; Given general number in T, split into	integer part in W; and fraction in T, rounding.;	EXPORT SPLIT2SPLIT2		;       	JSR KLUGE42	JSR KLUGE64	JSR CLRINEXACT	; Dont' record rounding error	LDX #F_W	; Integer part	EXPORT KLUGE90KLUGE90		;       	LDY #F_DEST	; All of number	EXPORT KLUGE91KLUGE91		;       	LDA #FOSUB	JMP CALL_SANE;; Split T for EXP(x) and EXP(x) - 1.; Let T = K * LN(2)	+ F.  Want W=K and T=F/LN(2).; Find F with REM modulo LN(2); then subtract from T and divide by LN(2); to get K.	EXPORT SPLITSPLIT		;       	JSR KLUGE42	LDX #F_FPKLOGE2	JSR KLUGE99	LDX #F_DEST	LDY #F_W	JSR KLUGE91	; T - (T REM LN(2))	in W	LDX #F_FPKLOGE2	LDY #F_W	JSR KLUGE93	JSR KLUGE64	LDX #F_FPKLOGE2	JSR KLUGE92	JMP CLRINEXACT	; ... and exit;; EXP(x)-1 and EXP2(x)-1 share the same	exception code.  Then both exploit; EXAPPROX for the root computation  2^frac - 1.;	EXPORT EXP1TOPEXP1TOP		;       	LDA <SRC2_CLASS	BPL EXP1FINITE	; Handle finite non-zero case	CMP #FCZERO	BEQ EXPEASY	; Handle zero case;		        ; Y^+-0 - 1	is +-0	LDA <SRC2_SIGN	; 0=positive, 1=negative	BPL EXPEASY	JMP M1STUFF	;Y^-INF - 1 is -1	EXPORT EXPEASYEXPEASY		;       	JMP RESULTDELIVERED	; Y^+INF - 1 is +INF	EXPORT EXP1FINITEEXP1FINITE		;       ;; If the number is denormalized, have easy case whether EXP1 or EXP21.;	LDA #BTLOGBASE2	BIT <OPCODE	; Nonzero if EXP2X	BEQ EXP1R;; As above, for 2^T-1 split T into fraction part in T and integer; in W, and got to root computation.;	EXPORT EXP21REXP21R		;       	LDA <SRC2_CLASS	BEQ EXP21RNORM	; Handle normal	LDX #F_FPKLOGE2	JSR KLUGE20	EXPORT EXP1OUTEXP1OUT		;       	JSR FORCEUFLOW	JSR FORCEINEXACT	JMP EXP1RDONE	EXPORT EXP21RNORMEXP21RNORM		;       	JSR SPLIT2	JMP EXP1ROOT;; For E^T-1, split T into K and F/LN(2), where T = K*LN(2) + F.; If overflow, then	force INF or -1...;	EXPORT EXP1REXP1R		;       	LDA <SRC2_CLASS	; 0-norm, 1-denorm	BNE EXP1OUT	; Handle denorm;		        ; E^T-1 is T, with UFLOW;		        ; for now.	JSR SPLIT	JSR TESTOFLOW	BEQ EXP1ROOT	JSR KLUGE17	JMP M1STUFF	; Force -1;; This is the root of V^X-1 where V is 2 or E.; Compute (2^T - 1)	for fraction T.  Then if (integer) W is; nonzero, finish off with (((2^T - 1) + 1) * 2^W) - 1.;	EXPORT EXP1ROOTEXP1ROOT		;       	JSR EXAPPROX	; 2^T - 1	LDX #F_W	LDY #F_FPK0	JSR KLUGE28	FBEQ EXP1RDONE	JSR KLUGE3	LDX #F_FPK1	; Finally, subtract	1	JSR KLUGE90;; Reset underflow, which cannot occur if W (as in 2^W) is nonzero.;	JSR CLEARUFLOW	EXPORT EXP1RDONEEXP1RDONE		;       	JMP RESULTDELIVERED	EXPORT KLUGE3KLUGE3		;       	JSR KLUGE96	EXPORT KLUGE36KLUGE36		;       	MOVECA <DEST,<A0_ADDR ; Result Ptr	MOVECA <W_TEMP,<OP1_ADDR ; Integer part	JMP SCALBXX	; ((2^T - 1) + 1) *	2^W;; Compute approximate (2^T) - 1) for T in DEST.; Uses cells X,Y (extended) and temporary ptrs A0_ADDR, OP1_ADDR.; Expression has the form;      ( 2 * T * P(T*T)) / (Q(T*T) - (T	* P(T*T)) ).; One special case:	if T is 0, just return 0, and don't set; the inexact flag.;	EXPORT EXAPPROXEXAPPROX		;       	LDX #F_DEST	LDY #F_FPK0	; Compare input with 0	JSR KLUGE28	FBNE EXPHARD	RTS	EXPORT EXPHARDEXPHARD		;       	JSR KLUGE51	LDX #F_Y	LDY #F_Y	JSR KLUGE25	LDY #F_EXP21P	; Exponent P coefs	JSR KLUGE32	JSR KLUGE19	LDY #F_EXP21Q	JSR KLUGE32	LDX #F_DEST	LDY #F_X	JSR KLUGE91	LDX #F_FPK2	; 2.0	JSR KLUGE20	LDX #F_X	JSR KLUGE92;; Finally, set inexact and clear any underflow messages.;	JSR FORCEINEXACT	JMP CLEARUFLOW	; ...and exit.	ENDP;;;;; Raise extended dst to integer src power.;	EXPORT KLUGE37KLUGE37	PROC	LONGA OFF	LONGI OFF	MOVE2 <I_SRC,<J_TEMP	RTS	EXPORT XPWRITOPXPWRITOP		;       	LDA <I_SRC	ORA <I_SRC+1	; See if = 0	BNE z3s05	JMP P1STUFF	; Any^0 is 1Z3S05	LDA <SRC2_CLASS	BPL FINPWRI	; Nonzero^I; Get here if INF^I	of 0^I.  If I is negative, must reciprocate; (signaling div by	0 in case of 0^-N).	 If I is even, must	clear; sign.;	JSR KLUGE37	LSR <J_TEMP+1	; Get odd bit of I into C	ROR <J_TEMP	BCS z3s01	; Carry bit set if odd	JSR KLUGE63Z3S01	LDA <I_SRC+1	BMI z3s02	JMP RESULTDELIVERED	; (INF or ZERO)^POSZ3S02	LDA <SRC2_CLASS	CMP #FCZERO	BEQ ZPWRNEG	; INF or ZERO?	JSR KLUGE61	BMI Z3S03	JMP POSTUFF	; +INF^NEG is +0Z3S03	JMP MOSTUFF	; -INF^NEG is -0	EXPORT ZPWRNEGZPWRNEG		;       	JSR KLUGE61	BMI z4s04	JMP DIVPOSTUFF	; +0^NEG is +INFZ4S04	JMP DIVMOSTUFF	; -0^NEG is -INF;; NONZERO^I is broken into two cases:;   If I is small, then just multiply out.  Note that sign perseveres if;   I is odd.;   Otherwise, convert I to extended and evaluate with exponentials.;; 6502 NOTE:  Since	'SMALLEXP' = 255, only need to look at the high byte; to see if a number is smaller than that.  Also, once I decide to use; XPWRK algorithm, I will be working with a one byte quantity (for k).;	EXPORT FINPWRIFINPWRI		;       	JSR KLUGE4	LDA <D0_TEMP+1	BNE XPWRBIG	; Use LOG and EXP	JSR XPWRK	; Multiply out	JMP RESULTDELIVERED;; Integer power is too large to multiply out, so convert to	extended; and use general x^y routine.  Make copy of integer in cell W.;	EXPORT XPWRBIGXPWRBIG		;       	JSR KLUGE61	AND #$80	; show only sign bit	PHA	JSR KLUGE63	LDX #F_ISRC	; Addr of Int	LDY #F_SRC	LDA #FOZ2X	; Convert int to ext	JSR CALLI_SANE	JSR XPWRY	; Compute (DEST)^(SRC);; Note that XPWRY mujst preserve the integer value in ISRC;	PLA	; Retrieve sign of input	BPL z5s03	; If positive, don't care	LSR <I_SRC	; Low bit to carry	BCC z5s03	; Carry set if odd	JSR KLUGE62Z5S03	JMP RESULTDELIVERED	EXPORT KLUGE61KLUGE61		;       	LDX #F_DEST	LDY #FOCLASS	EXPORT KLUGE60KLUGE60		;       	JMP CALL1_SANE	EXPORT KLUGE62KLUGE62		;       	LDX #F_DEST	EXPORT KLUGE67KLUGE67		;       	LDY #FONEG	BNE KLUGE60	EXPORT KLUGE63KLUGE63		;       	LDX #F_DEST	EXPORT KLUGE68KLUGE68		;       	LDY #FOABS	BNE KLUGE60	EXPORT KLUGE64KLUGE64		;       	LDX #F_W	EXPORT KLUGE66KLUGE66		;       	LDY #FORTI	BNE KLUGE60	ENDP;; Raise T to the power ISRC, leaving the result in DEST_ADDR.  D0TEMP =; ABS (ISRC).  If ISRC is negative, evaluate the positive power and; reciprocate at the end.  Know ISRC is	nonzero.  Sign of DEST_ADDR is; propagated correctly.  Trash A0_TEMP,	A1_TEMP, D0_TEMP, I_TEMP, W_TEMP,; J_TEMP, X_TEMP.;	EXPORT XPWRKXPWRK	PROC	LONGA OFF	LONGI OFF	JSR KLUGE49	JSR XPWRKLOOP;; Now that loop is finished, produce 1 * T^|I| or 1 / T^|I|, depending; on sign of I.  If	overflow or underflow has occurred and I is negative,; redo compuation with pre-reciprocated	T.;	LDA <I_SRC+1	; Is I negative?	BMI XPWRKDIV	EXPORT XPWRKSTOREXPWRKSTORE		;       	LDX #F_W	; T <-- T^|I|	LDY #F_DEST	JMP KLUGE40	EXPORT XPWRKDIVXPWRKDIV		;       	LDX #F_FPK1	; T <-- 1	JSR KLUGE8	JSR TESTUFLOW	BNE XPWRKCLEAR	JSR TESTOFLOW	BNE XPWRKCLEAR	EXPORT KLUGE95KLUGE95		;       	LDX #F_W	; W = T^|I| from XPWRKLOOP	EXPORT KLUGE92KLUGE92		;       	LDY #F_DEST	EXPORT KLUGE93KLUGE93		;       	LDA #FODIV	JMP CALL_SANE	EXPORT XPWRKCLEARXPWRKCLEAR		;       	JSR CLEAROFLOW	JSR CLEARUFLOW	LDX #F_X	; Saved input T atop T^|I|	JSR KLUGE92	JSR KLUGE4	JSR XPWRKLOOP	JMP XPWRKSTORE;; Input:   D0_TEMP = positive integer K	 ( <255 );          DEST_ADDR = X; Output:  W_TEMP =	X^K; Trashes: D0_TEMP;	EXPORT XPWRKLOOPXPWRKLOOP		;       	LDX #F_FPK1	; See result with 1.0	JSR KLUGE41	JMP XKLPENTRY	EXPORT XKLPTOPXKLPTOP		;       	LDX #F_DEST	JSR KLUGE20	EXPORT XKLPENTRYXKLPENTRY		;       	LSR <D0_TEMP	; Get low bit of k into C	BCC XKLPSKIP	LDX #F_DEST	; T^(2^I)	JSR KLUGE24	EXPORT XKLPSKIPXKLPSKIP		;       	LDA <D0_TEMP	; Any more bits?	BNE XKLPTOP	RTS;; Simple routine to	compute (DEST)^(SRC) into (DEST).; Know that (DEST) is positive.  Know that the FMULX will never; encounter 0 * INF, so extreme cases, like INF^3, will be handled; correctly.;	EXPORT XPWRYXPWRY		;       	LDX #F_DEST	; Copy Dest into temporary;		        ; accumulator	JSR KLUGE44	LDY #FOLOG2X	; LOG2(ACCUM)	EXPORT KLUGE5KLUGE5		;       	JSR KLUGE30	JSR KLUGE26	; SRC * LOG2 (ACCUM)	LDY #FOEXP2X	; ACCUM^SRC	JSR KLUGE30	EXPORT KLUGE43KLUGE43		;       	LDX #F_ACCUM	; Move accum back into Dest	JMP KLUGE8	EXPORT KLUGE45KLUGE45		;       	LDX #F_SRC2	EXPORT KLUGE44KLUGE44		;       	LDY #F_ACCUM	JMP MOVEIT	ENDP;; END OF FILE;; X^Y, Compound, Annuity;                  COPY           elems/ELEM3.O;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File:  Elem3.o			             ;;; For building 65816 Elems V0.0		             ;;; Status: First attempt		             ;;; Copyright Apple Computer, Inc., 1983-1986	             ;;; All Rights Reserved		             ;;;			             ;;; Written by C. Hausmann, 1983		             ;;;			             ;;; Modification History:		             ;;;      24Mar86 CRL	    Rewritten for 65816	             ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; General function x^y is beset by exceptional cases.;	EXPORT XPWRYTOPXPWRYTOP	PROC	LONGA OFF	LONGI OFF	LDA <SRC2_SIGN	; Is X=DEST negative?	BMI NEGPWRY	JSR XPWRYCOM	JMP RESULTDELIVERED;; Signal X^Y error and stuff a NAN.  Special entry accommodates branches from; within subroutines, in which case a return address must be popped.;	EXPORT XPWRY9ERRXPWRY9ERR		;       	PLA	; pop extra return address	PLA	EXPORT XPWRYERRXPWRYERR		;       	JSR CLRINEXACT	; Signal invalid only	LDA #NANPOWER	EXPORT KLUGE38KLUGE38		;       	STA <CLASS_CODE	LDA <SRC_SIGN	; Check that D0 corresponds;		        ; to this!	STA <CLASS_SIGN	JMP ERRORNAN;; If X is negative,	check that Y is integral;  otherwise error.; Save parity of Y to fix sign at end of XPWRYCOM.;	EXPORT NEGPWRYNEGPWRY		;       	LDA <SRC_CLASS	CMP #FCINF	BEQ XPWRYERR	; Y class - INF	LDX #F_SRC	; Y=SRC	JSR KLUGE41	LDX #F_SRC	JSR KLUGE66	LDX #F_SRC	JSR KLUGE66	JSR TESTINEXACT	BNE XPWRYERR;; NEG ^ INT requires that parity of Y be saved in cell J for later; setting of sign.	To find low bit of floating integer, divide by; 2 and test inexact.;	LDX #F_FPK2	; 2.0	LDY #F_W	JSR KLUGE93	JSR KLUGE64	LONGA ON	LONGI ON	REP #$30	; save flags, first	16 bit mode	LDY #FOGETENV	; set all 16 bits	JSR CALL0_SANE	; and place zero arg call	LONGA OFF	LONGI OFF	STX <I_TEMP	STY <I_TEMP+1	JSR CLRINEXACT	JSR KLUGE63	JSR XPWRYCOM	; Abs (DEST) ^ (SRC);; Fix sign of power, according to parity of Y.  The parity is stored in; the inexact flag,	saved in cell I.  It's in the high byte so just do; a bit test.;	LDA #FBINEXACT	BIT <I_TEMP+1	BEQ z1s01	; Negate if odd (inexact)	JSR KLUGE62Z1S01	JMP RESULTDELIVERED;; Common routine to	raise DEST to SRC power.; Know DEST >= 0 and SRC is not a NAN.; Have class codes in SRC2_CLASS and SRC_CLASS, respectively.; Can run through  2 ^ Y*LOG2(x)  code so long as won't multiply; INF and 0 to compute exponent.  As a minor detail, if Y is 0 or INF,; clear any inexact	that may have been set by LOG2(x).;; Since this is called as a subroutine,	exits to XPWRYERR must have a; special pop for the return address.;	EXPORT XPWRYCOMXPWRYCOM		;       	LDA <SRC2_CLASS	CMP #FCZERO	BNE NONPWRY;; 0 ^ some;	LDA <SRC_CLASS	CMP #FCZERO	BNE z2s02	JMP XPWRY9ERR	; 0^0 error, with;		        ; rts popZ2S02	LDA <SRC_SIGN	; Sign of Y	BPL z2s01;; 0 ^ nonzero;	JSR FORCEDIVZER	; Signal div by zero	LDX #F_FPKINF	; Stuff result and exit	BNE z2s03Z2S01	LDX #F_FPK0Z2S03	JMP KLUGE8;; nonzero ^ some;	EXPORT NONPWRYNONPWRY		;       	BPL FINPWRY	; Exit if X finite;; inf ^ some;	LDA <SRC_CLASS	CMP #FCZERO	BNE XPWRYOK	; Y = norm, denorm,	or INF	JMP XPWRY9ERR	; INF^0 is an error;; finite ^ some;	EXPORT FINPWRYFINPWRY		;       	LDA <SRC_CLASS	CMP #FCINF	BNE XPWRYOK	; FIN ^ FIN is ok;; finite ^ inf has the special case 1^INF which is an error.;	LDX #F_DEST	LDY #F_FPK1	JSR KLUGE28	FBNE XPWRYOK	JMP XPWRY9ERR;; Finally, compute finite^reasonable and return.; Two cases: if exponent is a small integer, then just multiply;; else use log and exp.  To check for an integer, try converting to; 16 bits.  Overflow is Invalid, rounding error is Inexact.; Must reset Invalid, but if Inexact the result will be anyway.;; 6502 NOTE: Unlike	the MAC routine, it	proves to be unnecessary to; save an extra copy of SRC_CLASS since	it is never modified in; call to XPWRK (in	the 6502 version).;	EXPORT XPWRYOKXPWRYOK		;       	LDX #F_SRC	; Exponent address index	LDY #F_ISRC	LDA #FOX2Z	; Convert to integer	JSR CALLI_SANE	LDA #FBIplusX	; logical OR of i,x	STA <EXCPTION	LDX #FOTESTXCP	JSR KLUGE31	; Either error?	BEQ z3s01	JSR CLEARINVALID	JMP XPWRYHARD	; Yes! So do it using log;		        ; and expZ3S01	JSR CLEARINVALID	; Clear undeserved error	JSR KLUGE4	LDA <D0_TEMP+1	BNE XPWRYHARD	JMP XPWRK	; Do it as an integer and;		        ; exit (k small)	EXPORT KLUGE4KLUGE4		;       	MOVE2 <I_SRC,<D0_TEMP	LDA <I_SRC+1	BPL z4s02	JSR KLUGE37	JSR NEGATE	MOVE2 <J_TEMP,<D0_TEMPZ4S02	RTS	EXPORT XPWRYHARDXPWRYHARD		;       	JSR CLRINEXACT	CLC	LDA <SRC_CLASS	JSR XPWRY	LDA <SRC_CLASS	CLC	LDA <SRC_CLASS	; Check for y = 0 or INF	BPL z5s01	JMP CLRINEXACT	; and return from thereZ5S01	RTS	ENDP;; Compute  DEST <--	(1 + SRC2)^SRC	 r = SRC2    n = SRC; Watch for special	cases:;          SRC2  < -1  is invalid;          else  SRC = 0 yields 1;          else  SRC2 = 0 and SRC = INF	if invalid;          else  SRC = INF yields 0 or INF according to SRC2;          else  SRC2 = -1 yields 0, 1,	or INF according to	SRC;          else  actually compute (1 + r)^n !!;	EXPORT COMPOUNDTOPCOMPOUNDTOP	PROC	LONGA OFF	LONGI OFF	LDX #F_SRC2	LDY #F_FPKM1	; -1	JSR KLUGE28	FBEQ z6s01	FBGT CMPGTM1	JMP ERRFINAN	; Unordered or less	than -1;; Get here if SRC2 is -1.  Check SRC for 0 or nonzero.;Z6S01	LDA <SRC_CLASS	CMP #FCZERO	BNE CMPM1N	EXPORT CMPTOZEROCMPTOZERO		;       	JMP P1STUFF	; (1 + some)^0 is +1	EXPORT CMPM1NCMPM1N		;       	LDA <SRC_SIGN	BPL CMPZERO	JMP DIVPOSTUFF	; (1 - 1)^NEG is +INF	EXPORT CMPZEROCMPZERO		;       	JMP POSTUFF	; (1 - 1)^POS is +0;; Get here if SRC2 (r) is > -1.;	EXPORT CMPGTM1CMPGTM1		;       	LDA <SRC_CLASS	CMP #FCZERO	BEQ CMPTOZERO	; (1 + some)^0 is +1	BPL CMPTOFIN	; Go do (1 + some)^FINITE;; Get here if (1 + some)^INF.  Check for 1^INF, an error, else have; INF or 0 according to SRC and SRC2.;	LDA <SRC2_CLASS	CMP #FCZERO	BNE z7s01	JMP ERRFINANZ7S01	LDA <SRC_SIGN	EOR <SRC2_SIGN	BNE CMPZERO	; Signs differ --> ZERO	JMP PINFSTUFF	; Signs same --> +INF;; Finally, compute (1 + reasonable)^finite with the usual...;	EXPORT CMPTOFINCMPTOFIN		;       	JSR KLUGE45	LDY #FOLOG21X	; LOG2 (1 + ACCUM)	JSR KLUGE5	JSR CLEAROFLOW	JSR CLEARUFLOW	JSR TESTINEXACT	BEQ z8s01	; Done if not inexact	JSR KLUGE61	CPX #FCNORM	; Normal - done	BEQ z8s01	CPX #FCINF	; Infinite - set oflow	BNE z8s02	JSR FORCEOFLOW	JMP RESULTDELIVEREDZ8S02	JSR FORCEUFLOW	; Zero, denorm - set uflowZ8S01	JMP RESULTDELIVERED;; Routine to stuff the financial NAN and go.;	EXPORT ERRFINANERRFINAN		;       	LDA #NANFINAN	JMP KLUGE38	ENDP;; Compute annuity factor:;     (1 - (1 + r)^-n ) / r; for  r = SRC2  and  n = SRC.; Multitudinous special cases handled piece by piece.;	EXPORT ANNUITYTOPANNUITYTOP	PROC	LONGA OFF	LONGI OFF	LDX #F_SRC2	; R	LDY #F_FPKM1	; -1	JSR KLUGE28	FBULT ERRFINAN	; R < -1 is an error	FBNE ANNOK;; Get here is have (1 - 1)^ANY.  Just check n = SRC.;	LDA <SRC_CLASS	CMP #FCZERO	BEQ ANNO	; ANN (-1, 0) is + 0	LDA <SRC_SIGN	; Check sign of nonzero N	BMI ANNM1	JMP DIVPOSTUFF	EXPORT ANNM1ANNM1		;       	JMP M1STUFF;; Know that R = SRC2 exceeds -1.  Check	first for N=SRC=0.;	EXPORT ANNOKANNOK		;       	LDA <SRC_CLASS	CMP #FCZERO	BNE ANNXN	EXPORT ANNOANNO		;       	JMP POSTUFF;; Now check for unusual, 0 or INF, R=SRC2.;	EXPORT ANNXNANNXN		;       	LDA <SRC2_CLASS	CMP #FCZERO	BEQ ANNSRC	; SRC2=0	BPL ANNROK	; Norm, Denorm	JMP ANNRINF	; Infinity;; R = SRC2 = 0.  Limit gives result of N = SRC.;	EXPORT ANNSRCANNSRC		;       	LDX #F_SRC	JMP KLUGE7;; R = SRC2 = +INF.	If N = SRC is nonnegative have 0, else test N=SRC vs -1.;	EXPORT ANNRINFANNRINF		;       	LDA <SRC_SIGN	BPL ANNO	; Force +0	LDX #F_SRC	; SRC	LDY #F_FPKM1	; -1	JSR KLUGE28	FBEQ ANNM1	; N = -1, stuff -1	FBLT z9s01	JMP MOSTUFFZ9S01	JMP MINFSTUFF;; Way down here, we	have R=SRC2 a normal or denormal number.; Last check is for	N=SRC=INF.;	EXPORT ANNROKANNROK		;       	LDA <SRC_CLASS	BPL ANNDOIT	; Norm or Denorm	LDA <SRC_SIGN	EOR <SRC2_SIGN	; Do R and N signs match	BNE ANNSRC	LDX #F_FPK1	; X <-- +1	JSR KLUGE50	LDX #F_SRC2	; Addr of R, divisor	LDY #F_X	JSR KLUGE93	LDX #F_X	; Dest <-- 1/R	JMP KLUGE7;; Finally, compute (1 - (1 + r)^-n ) / r.; Distinguish two cases:;      r normal:;               log2(1 + r);               n *	log2 (1 + r);               -n * log2 (1 + r);               2^(...) - 1;               1 -	2^(...);               (1 - 2^(...)) / r;;      r denormal:;               log	(1 + r) is about r;               n *	r;               -n * r;               e^(...) - 1;               (1 - e^(...)) / r;	EXPORT ANNDOITANNDOIT		;       	JSR KLUGE45	LDX #F_SRC2	LDY #F_Z	JSR MOVEIT	; Save extra copy of src2;		        ; because recursion trashes;		        ; original copy	LDA <SRC2_CLASS	; 0-normal, 1-denormal	BNE ANNALLLOG	; If denormal, skip	log2()	LDY #FOLOG21X	; LOG2 (1 + r)	JSR KLUGE30	EXPORT ANNALLLOGANNALLLOG		;       	JSR KLUGE26	LDX #F_ACCUM	JSR KLUGE67	LDA <SRC2_CLASS	; Recheck norm or denorm	BEQ ANN02	LDY #FOEXP1X	; Denorm case	JSR KLUGE30	JSR FORCEINEXACT	JMP ANN01	EXPORT ANN02ANN02		;       	LDY #FOEXP21X	; (1 + R)^-N - 1	JSR KLUGE30	EXPORT ANN01ANN01		;       	LDX #F_ACCUM	JSR KLUGE67	LDX #F_Z	; R	LDY #F_ACCUM	JSR KLUGE93	JSR CLEARUFLOW	JSR CLEAROFLOW	JSR KLUGE43	MOVECA <DEST,<OP0_ADDR;		        ; Set up for class function	JSR CLASSIFY	TXA	CMP #FCINF	BNE z10s03	; Is it INF?	JSR FORCEOFLOW	JMP ANNDOUTZ10S03	CMP #FCNORM	; Is it NORMAL?	BEQ ANNDOUT	JSR FORCEUFLOW	EXPORT ANNDOUTANNDOUT		;       	JMP RESULTDELIVERED	ENDP;; END OF FILE;;Constants;                  COPY           elems/ELEMC.O;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File:  ElemC.o			             ;;; For building 65816 Elems V0.0		             ;;; Status: First attempt		             ;;; Copyright Apple Computer, Inc., 1983-1986	             ;;; All Rights Reserved		             ;;;			             ;;; Written by C. Hausmann, 1983		             ;;;			             ;;; Modification History:		             ;;;      24Mar86 CRL	    Rewritten for 65816	             ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;	EXPORT COEFFSCOEFFS	PROC	EXPORT LOG21PLOG21P	DC.W 5	DC.B $FF,$3B,$CE,$F6,$AF,$46,$46,$B9,$F6,$3F	DC.B $EB,$FB,$61,$4D,$21,$32,$F4,$94,$F9,$3F	DC.B $93,$78,$44,$D9,$03,$89,$97,$DC,$FB,$3F	DC.B $05,$1D,$CA,$57,$46,$39,$9E,$9F,$FF,$3F	DC.B $9A,$DC,$EC,$46,$3A,$C5,$6B,$CD,$01,$C0	DC.B $E0,$FC,$E6,$BA,$E7,$97,$83,$B4,$01,$40	EXPORT LOG21QLOG21Q	DC.W 2	DC.B $00,$00,$00,$00,$00,$00,$00,$80,$FF,$3F	DC.B $1D,$5E,$0A,$CE,$C3,$35,$18,$B8,$00,$C0	DC.B $96,$1A,$F4,$DD,$0E,$DF,$3E,$FA,$FF,$3F	EXPORT EXP21PEXP21P	DC.W 3	DC.B $79,$9B,$20,$1B,$C8,$90,$88,$FF,$EE,$BF	DC.B $2F,$27,$13,$B8,$EF,$84,$5C,$DA,$F9,$3F	DC.B $45,$FD,$0F,$F8,$EA,$BA,$D3,$97,$03,$40	DC.B $0C,$FF,$BE,$95,$A1,$71,$86,$AB,$09,$40	EXPORT EXP21QEXP21Q	DC.W 2	DC.B $00,$00,$00,$00,$00,$00,$00,$80,$FF,$3F	DC.B $B4,$5A,$4B,$98,$02,$70,$48,$D5,$06,$40	DC.B $80,$07,$B7,$96,$2E,$61,$75,$F7,$0A,$40	EXPORT FPK1FPK1	DC.B $00,$00,$00,$00,$00,$00,$00,$80,$FF,$3F	EXPORT FPKM1FPKM1	DC.B $00,$00,$00,$00,$00,$00,$00,$80,$FF,$BF	EXPORT FPK2FPK2	DC.B $00,$00,$00,$00,$00,$00,$00,$80,$00,$40	EXPORT FPK3FPK3	DC.B $00,$00,$00,$00,$00,$00,$00,$C0,$00,$40	EXPORT FPKMAXINTFPKMAXINT	DC.B $00,$00,$00,$00,$00,$00,$FE,$FF,$0D,$40	EXPORT FPKSQRT2FPKSQRT2	DC.B $84,$64,$DE,$F9,$33,$F3,$04,$B5,$FF,$3F	EXPORT FPKHALFFPKHALF	DC.B $00,$00,$00,$00,$00,$00,$00,$80,$FE,$3F	EXPORT FPKSQRTHALFFPKSQRTHALF	DC.B $84,$64,$DE,$F9,$33,$F3,$04,$B5,$FE,$3F	EXPORT FPKFOURTHFPKFOURTH	DC.B $00,$00,$00,$00,$00,$00,$00,$80,$FD,$3F	EXPORT FPK34FPK34	DC.B $00,$00,$00,$00,$00,$00,$00,$C0,$FE,$3F	EXPORT FPK78FPK78	DC.B $00,$00,$00,$00,$00,$00,$00,$E0,$FE,$3F	EXPORT FPKPI2FPKPI2	DC.B $35,$C2,$68,$21,$A2,$DA,$0F,$C9,$FF,$3F	EXPORT FPKPI4FPKPI4	DC.B $35,$C2,$68,$21,$A2,$DA,$0F,$C9,$FE,$3F	EXPORT FPKEFPKE	DC.B $9B,$4A,$BB,$A2,$58,$54,$F8,$AD,$00,$40	EXPORT FPKLOGE2FPKLOGE2	DC.B $AC,$79,$CF,$D1,$F7,$17,$72,$B1,$FE,$3F	EXPORT FPK0FPK0	DC.B $00,$00,$00,$00,$00,$00,$00,$00,$00,$00	EXPORT FPKM0FPKM0	DC.B $00,$00,$00,$00,$00,$00,$00,$00,$00,$80	EXPORT FPKINFFPKINF	DC.B $00,$00,$00,$00,$00,$00,$00,$00,$FF,$7F	EXPORT FPKMINFFPKMINF	DC.B $00,$00,$00,$00,$00,$00,$00,$00,$FF,$FF	EXPORT F_MAXINTF_MAXINT	DC.B $FF,$7F	EXPORT F_M1F_M1	DC.B $FF,$FF;; If the Trigs are not required, then this location specifies the end; of the code file (ptr at start of program points to this address).;	EXPORT SINQSINQ	DC.W 3	DC.B $00,$00,$00,$00,$00,$00,$00,$80,$FF,$3F	DC.B $30,$5A,$A8,$A6,$44,$B8,$D8,$88,$07,$40	DC.B $20,$23,$79,$09,$49,$8A,$15,$8A,$0E,$40	DC.B $2B,$F2,$63,$FE,$26,$FE,$A9,$FA,$13,$40	EXPORT SINPSINP	DC.W 3	DC.B $F5,$CB,$F5,$43,$AE,$86,$50,$C2,$FE,$BF	DC.B $A2,$6B,$E7,$BE,$66,$EC,$76,$9E,$06,$40	DC.B $01,$AA,$C4,$C4,$D6,$A1,$51,$AF,$0C,$C0	DC.B $CE,$F6,$97,$A9,$C4,$FE,$1B,$A7,$11,$40	EXPORT COSQCOSQ	DC.W 3	DC.B $00,$00,$00,$00,$00,$00,$00,$80,$FF,$3F	DC.B $85,$96,$DF,$FB,$95,$6A,$D9,$A6,$07,$40	DC.B $6B,$15,$5D,$E8,$65,$EA,$A7,$C7,$0E,$40	DC.B $B2,$52,$17,$7B,$1C,$87,$6E,$D2,$14,$40	EXPORT COSPCOSP	DC.W 3	DC.B $58,$D7,$F6,$A6,$D7,$18,$7E,$D5,$FB,$BF	DC.B $72,$D0,$B3,$32,$7E,$93,$64,$E3,$03,$40	DC.B $45,$C0,$6B,$58,$56,$40,$2D,$A6,$0A,$C0	DC.B $7A,$8C,$0F,$52,$68,$AF,$49,$8C,$10,$40	EXPORT TANQTANQ	DC.W 3	DC.B $00,$00,$00,$00,$00,$00,$00,$80,$FF,$BF	DC.B $55,$09,$C0,$83,$24,$03,$13,$B5,$05,$40	DC.B $CF,$E0,$62,$57,$42,$B2,$FF,$D1,$09,$C0	DC.B $AB,$66,$76,$93,$09,$93,$90,$E1,$0A,$40	EXPORT TANPTANP	DC.W 3	DC.B $38,$28,$9B,$D7,$63,$33,$FC,$B1,$E9,$BF	DC.B $D1,$4C,$C7,$3E,$D8,$71,$9D,$AA,$FD,$3F	DC.B $BB,$7D,$65,$B9,$24,$8E,$CD,$E9,$03,$C0	DC.B $36,$18,$4B,$9D,$70,$36,$9A,$F0,$07,$40	EXPORT ATANQATANQ	DC.W 4	DC.B $AD,$5D,$FA,$2A,$AE,$1E,$D3,$98,$FF,$3F	DC.B $D9,$EF,$CD,$B3,$D8,$4C,$79,$8F,$03,$40	DC.B $68,$B3,$B8,$70,$85,$ED,$37,$8E,$05,$40	DC.B $B8,$F3,$59,$AC,$A1,$BE,$A4,$CD,$05,$40	DC.B $56,$C6,$F0,$4C,$55,$9C,$05,$C4,$04,$40	EXPORT ATANPATANP	DC.W 4	DC.B $00,$00,$00,$00,$00,$00,$00,$80,$FF,$3F	DC.B $30,$0E,$92,$1F,$13,$6C,$3B,$A2,$02,$40	DC.B $6F,$48,$3A,$FA,$3D,$59,$C8,$C3,$03,$40	DC.B $45,$D9,$F5,$DD,$38,$68,$AE,$82,$03,$40	DC.B $00,$00,$00,$00,$00,$00,$00,$00,$00,$00	EXPORT FPKX2FPKX2	DC.B $6A,$E2,$98,$81,$2C,$3A,$CD,$93,$FE,$3F	EXPORT FPKX2FX2FPKX2FX2	DC.B $62,$64,$DB,$5F,$B1,$86,$2A,$DC,$FA,$3F	EXPORT FPKATNCONSFPKATNCONS	DC.B $8A,$B1,$6A,$F6,$F4,$A2,$30,$89,$FD,$3F	EXPORT FPKARANDFPKARAND	DC.B $00,$00,$00,$00,$00,$00,$4E,$83,$0D,$40	EXPORT FPKPRANDFPKPRAND	DC.B $00,$00,$00,$00,$FE,$FF,$FF,$FF,$1D,$40	ENDP;	EXPORT OPERANDOPERAND	PROC	DC.W DEST	DC.W SRC	DC.W SRC2	DC.W I_SRC	DC.W I_TEMP	DC.W J_TEMP	DC.W W_TEMP	DC.W X_TEMP	DC.W Y_TEMP	DC.W Z_TEMP; Need to define ptrs to the tables of coefficients and constants so that; they can be pushed onto the stack by address.;	EXPORT C_LOG21PC_LOG21P	DC.W LOG21P	EXPORT C_LOG21QC_LOG21Q	DC.W LOG21Q	EXPORT C_EXP21PC_EXP21P	DC.W EXP21P	EXPORT C_EXP21QC_EXP21Q	DC.W EXP21Q	EXPORT C_FPK1C_FPK1	DC.W FPK1	EXPORT C_FPKM1C_FPKM1	DC.W FPKM1	EXPORT C_FPK2C_FPK2	DC.W FPK2	EXPORT C_FPK3C_FPK3	DC.W FPK3	EXPORT C_FPKMAXINTC_FPKMAXINT	DC.W FPKMAXINT	EXPORT C_FPKSQRT2C_FPKSQRT2	DC.W FPKSQRT2	EXPORT C_FPKHALFC_FPKHALF	DC.W FPKHALF	EXPORT C_FPKSQTHALFC_FPKSQTHALF	DC.W FPKSQRTHALF	EXPORT C_FPKFOURTHC_FPKFOURTH	DC.W FPKFOURTH	EXPORT C_FPK34C_FPK34	DC.W FPK34	EXPORT C_FPK78C_FPK78	DC.W FPK78	EXPORT C_FPKPI2C_FPKPI2	DC.W FPKPI2	EXPORT C_FPKPI4C_FPKPI4	DC.W FPKPI4	EXPORT C_FPKEC_FPKE	DC.W FPKE	EXPORT C_FPKLOGE2C_FPKLOGE2	DC.W FPKLOGE2	EXPORT C_FPK0C_FPK0	DC.W FPK0	EXPORT C_FPKM0C_FPKM0	DC.W FPKM0	EXPORT C_FPKINFC_FPKINF	DC.W FPKINF	EXPORT C_FPKMINFC_FPKMINF	DC.W FPKMINF	EXPORT C_SINQC_SINQ	DC.W SINQ	EXPORT C_SINPC_SINP	DC.W SINP	EXPORT C_COSQC_COSQ	DC.W COSQ	EXPORT C_COSPC_COSP	DC.W COSP	EXPORT C_TANQC_TANQ	DC.W TANQ	EXPORT C_TANPC_TANP	DC.W TANP	EXPORT C_ATANQC_ATANQ	DC.W ATANQ	EXPORT C_ATANPC_ATANP	DC.W ATANP	EXPORT C_FPKX2C_FPKX2	DC.W FPKX2	EXPORT C_FPKX2FX2C_FPKX2FX2	DC.W FPKX2FX2	EXPORT C_FPKATNCONSC_FPKATNCONS	DC.W FPKATNCONS	EXPORT C_FPKARANDC_FPKARAND	DC.W FPKARAND	EXPORT C_FPKPRANDC_FPKPRAND	DC.W FPKPRAND	DC.W EXCPTION	DC.W OLD_ENV	DC.W SAVE_ENV	DC.W V_TEMP	EXPORT C_MAXINTC_MAXINT	DC.W F_MAXINT	ENDP;; END OF FILE;; Sin, Cos, Tan, ATan, Random;                  COPY           elems/ELEM4.O.A;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File:  Elem4.O.A			             ;;; For building 65816 Elems V0.0		             ;;; Status: First attempt		             ;;; Copyright Apple Computer, Inc., 1983-1986	             ;;; All Rights Reserved		             ;;;			             ;;; Written by C. Hausmann, 1983		             ;;;			             ;;; Modification History:		             ;;;      24Mar86 CRL	    Rewritten for 65816	             ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; Sine function.; Input:  DEST	 = operand T;         SRC2_CLASS = class (-4..1);         SRC2_SIGN	 = sign of T; Output: DEST	 = result; Uses:   A0_ADDR..A2_ADDR, OP1_ADDR;         Cells: W_TEMP, X_TEMP, Y_TEMP;;; About the argument reduction:  T is reduced MOD approximate pi/2,; leaving the magnitude no bigger than approximate pi/4.; Recall the identities:;       sin (T)	          =  sin (T);       sin (pi/2 +	T)        =  cos (T);       sin (pi + T)          = -sin (T);       sin (3pi/2 + T)       = -cos (T);       sin (2pi + T)         =  sin (T); Then if input T =	q*(pi/2) + r,;       q mod 2 determines whether to use sin (0) or cos (1), and;       q mod 4 determines whether to negate result (2 or 3).;;	EXPORT SINTOPSINTOP	PROC	LONGA OFF	LONGI OFF	JSR KLUGE6	BNE SINCOSCOM	JMP RESULTDELIVERED	; SIN (+-0) is +-0SINCOSCOM	BPL z1s05	JMP ERRORNAN	; SIN (INF) is illegal;; Have finite, nonzero argument;Z1S05	JSR TRIGREDUCTION	; T <-- T REM PI/2	LDA #$1	BIT <D2_TEMP	BNE z1s01	JSR SINGUTS	; Even, use SIN	JMP z1s03Z1S01	JSR COSGUTS	; Odd, use COSZ1S03	LDA #$0	; Quo MOD 4	STA <D2_TEMP+1	LDA <D2_TEMP	AND #$3	SEC	SBC #$2	; >= 0 only if MOD 2 or 3	STA <D2_TEMP	LDA <D2_TEMP+1	SBC #$0	STA <D2_TEMP+1	BMI TRIGFINI	JSR KLUGE62;; Common trig finish:;       Clear uflow, except when denormalized.;       Set inexact.;       If result is denormal, set underflow.;       Exit.;	EXPORT TRIGFINITRIGFINI		;       	JSR CLEARUFLOW	; Will check for error later	JSR FORCEINEXACT	JSR KLUGE61	CPX #FCDENORM	BNE z2s13	JSR FORCEUFLOWZ2S13	JMP RESULTDELIVERED;; Cosine function.; Input:  DEST	 = operand T;         SRC2_CLASS = class (-4..1);         SRC2_SIGN	 = sign of T; Output: DEST	 = result; Uses:   A0_ADDR..A2_ADDR, OP1_ADDR;         Cells: W_TEMP, X_TEMP, Y_TEMP;;; About the argument reduction:  T is reduced MOD approximate pi/2,; leaving its magnitude no bigger than approximate pi/4.; Recall the identities:;       cos (T)	             =  cos	(T);       cos (pi/2 +	T)           = -sin	(T);       cos (pi + T)             = -cos	(T);       cos (3pi/2 + T)          =  sin	(T);       cos (2pi + T)            =  cos	(T); Then if input T =	q*(pi/2) + r,;      q mod 2 determines whether to use cos (0) or sin (1), and;      (q+1) mod 4 determines whether to negate result (2 or 3).;;;	EXPORT KLUGE39KLUGE39		;       	LDA <SRC2_SIGN	STA <CLASS_SIGN	LDA #NANTRIG	STA <CLASS_CODE	RTS	EXPORT COSTOPCOSTOP		;       	JSR KLUGE39	LDY #$0	; Quotient adjustment	STY <D2_TEMP+1	; Quo <-- 1	INY	STY <D2_TEMP	LDA <SRC2_CLASS	CMP #FCZERO	BNE SINCOSCOM	JMP P1STUFF	; COS (+-0) is 1;; Reduce DEST mod approximate pi/2, adding quotient to D2.; Input:  DEST    =	operand T;         D2_TEMP =	quotient adjustment; Output: DEST    =	reduced argument;         D2_TEMP =	adjusted quotient; Uses:   J_TEMP  =	quotient;	EXPORT TRIGREDUCTIONTRIGREDUCTION		;       	LDX #F_FPKPI2	; Approximate PI/2	JSR KLUGE99	; T REM (PI/2), low	byte;		        ; of quo in	X, sign in X.hi;; Move QUO to J_TEMP - converting to 2 byte quantity;	STZ J_TEMP+1	TXA	AND #$7F	STA J_TEMP	CPY #0	BEQ Z3S01	JSR NEGATE	; Negate J_TEMP if neg QUO;; Add QUO to quotient adjustment;Z3S01	CLC	LDA <D2_TEMP	ADC <J_TEMP	STA <D2_TEMP	LDA <D2_TEMP+1	ADC <J_TEMP+1	STA <D2_TEMP+1	RTS;; Evaluate sin (T) for reduced |T| <= pi/4.; Use approximation	(S = T*T)    T - (T*S*(P(S) / Q(S))); Input:  DEST	= T; Output: DEST	= sin (T); Uses:   A0_ADDR -	A2_ADDR, OP1_ADDR;         Cells: W_TEMP, X_TEMP, Y_TEMP; Note use of sin/cos common routine depends on placement of Q coef table; immediately before P coef table.;SINGUTS	LDA #F_SINQ	JSR POVERQ	; X <-- P/Q;		        ; Z <-- T^3	LDX #F_ACCUM	; ACCUM = T^3	JSR KLUGE21KLUGE94	LDX #F_X	; X	JMP KLUGE90;; Common routine for trig functions quts.; Input:  DEST	    = operand T;         Accum	    = index to Q coef table, with P immediately after in;	      memory; Output: W_TEMP	    = T*T;         Z_TEMP	    = T*T*T;         X_TEMP	    = (T*T) * (P(T*T) / Q(T*T)); Uses  : Y_TEMP	    = Q(T*T);         A0_addr, A2_addr  (as temporary pointers);	EXPORT T2POVERQT2POVERQ		;       	JSR POVERQ	JSR KLUGE22	LDX #F_ACCUM	; POVERQ does not alter Z.	EXPORT KLUGE48KLUGE48		;       	LDY #F_Z	; To deliver T^3 in	Z, it	JMP MOVEIT	;    must transfer from ACCUM;; Common routine for trig functions guts.; Called by T3POVERQ and ATANGUTS.; Input:  DEST	    = operand T;         OP1_Addr	    = ptr to Q coef	table, with P immediately after in;	      memory; Output: W_TEMP	    = T*T;         X_TEMP	    = (P(T*T) / Q(T*T));         ACCUM	    = T^3; Uses  : Y_TEMP	    = Q(T*T);         A0_addr, A2_addr  (as temporary pointers);;    NOTE : Use of #F_ACCUM added by C.R. Lewis on 2-Feb-84	to avoid trashing;           Z_DEST.	 Changes both here and in T2POVERQ.;	EXPORT POVERQPOVERQ		;       	STA <I_TEMP	; Index to table of	ptr to coefs	JSR KLUGE42	LDX #F_W	; W	JSR KLUGE24;; Compute Z = T^3;	LDX #F_W	; W = T*T	JSR KLUGE44	; Copy W into ACCUM	LDX #F_DEST	; Dest = T	JSR KLUGE27;; Compute P/Q;	LDX #F_Y	; Result field	JSR KLUGE33	; Y_TEMP <-- Q (T*T)	INC <I_TEMP	INC <I_TEMP	LDX #F_X	; Result field	JSR KLUGE33	; X <-- P(T*T)	LDX #F_Y	; P(T*T)	LDY #F_X	; Q(T*T)	JMP KLUGE93;; Evaluate cos (T) for reduced |T| <= pi/4.; Use approximation	(S = T*T):;    (S < 1/4):	   1 - S/2  +  S*S*(P(S) /Q(S));    else:	   with Z = |X| - 0.5;	   0.875 - (Z/2 + (Z*Z/2 - S*S*(P(S) / Q(S)))); Input:  DEST	= T; Output: DEST	= cos (T); Uses:   A0_ADDR -	A2_ADDR, OP1_ADDR;         cells:  W_TEMP, X_TEMP, Y_TEMP; Note use of sin/cos common routine depends on placement of Q coef table; immediately before P coef table.;COSGUTS	LDA #F_COSQ	; COS Q coef table,;		        ; P thereafter	JSR T2POVERQ	; W <-- T*T;		        ; Z <-- T^3;		        ; X <-- T^2*P/Q	JSR KLUGE22;; Now compare T*T in W with 1/4, to determine which formula	to continue with.;	LDX #F_W	; W	LDY #F_FPKFOURTH	; 1/4	JSR KLUGE28	FBGT CGBIG;; Finish with first	formula above.;	JSR KLUGE23	LDX #F_W	; W	LDY #F_X	; X = T^4 * P/Q	JSR KLUGE91	LDX #F_X	; Result = current X	JSR KLUGE8	LDX #F_FPK1	; 1	JMP KLUGE97	; SAME AS TGFIN;; Evaluate long form of expression.;CGBIG	JSR KLUGE63	LDX #F_FPKHALF	; 1/2	JSR KLUGE90	JSR KLUGE42	JSR KLUGE23	LDX #F_W	; W	JSR KLUGE20	LDX #F_X	; X = T^4*P/Q	JSR KLUGE90	LDX #F_W	; W = T'/2	JSR KLUGE97	JSR KLUGE62	LDX #F_FPK78	; 0.875 = 7/8	JMP KLUGE97	; SAME AS TGFIN	ENDP;; END OF FILE;;                  COPY           elems/ELEM4.O.B;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; File:  Elem4.o.b			             ;;; For building 65816 Elems V0.0		             ;;; Status: First attempt		             ;;; Copyright Apple Computer, Inc., 1983-1986	             ;;; All Rights Reserved		             ;;;			             ;;; Written by C. Hausmann, 1983		             ;;;			             ;;; Modification History:		             ;;;      24Mar86 CRL	    Rewritten for 65816	             ;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;; Tangent function.; Input:   DEST	= operand T;          SRC2_CLASS = class (-4..1);          SRC2_SIGN  = sign  ($0-positive, $80 - negative); Output:  DEST	= result; Uses  :  A0_ADDR - A2_ADDR, OP1_ADDR;          cells:  W_TEMP, X_TEMP, Y_TEMP, D2_TEMP;; About the argument reduction:  T is reduced MOD approximate pi/2,; leaving its magnitude no bigger than approximate pi/4.; Recall the identities:;        tan (T)	            =  tan(T);        tan(pi/2 +	T)          =  -1/tan(T);        tan (pi + T)           =  tan (T); Then if input T =	q*(pi/2) + r,;     q mod 2 determines whether to negate and reciprocate tan.;	EXPORT TANTOPTANTOP	PROC	LONGA OFF	LONGI OFF	JSR KLUGE6	BPL z4s01	JMP ERRORNAN	; INF is illegalZ4S01	BNE z4s02	JMP RESULTDELIVERED	; TAN(+-0) is +-0;; Have finite, nonzero argument.;Z4S02	JSR TRIGREDUCTION	JSR TANGUTS;;; check q mod 2;	ROR <D2_TEMP	; C bit <-- Quo mod	2	BCC z4s21	JSR KLUGE62	JSR KLUGE34	JSR TESTDIVZER	; Result = +/-INF?	BEQ z4s21	JSR KLUGE62Z4S21	JMP TRIGFINI	EXPORT KLUGE6KLUGE6		;       	JSR KLUGE39	STZ <D2_TEMP+1	; D2_TEMP <-- 0	STZ <D2_TEMP	LDA <SRC2_CLASS	CMP #FCZERO	RTS;; Evaluate tan (T) for |T| <= pi/4.; Use formulas:  (S	= T*T);      S <= 1/4:	       T + (T^3/3 +	T^5*P(S)/Q*S));      else:	       T' = (T - 3/4)/3;	       T  + S/4 + S*(T' + T^3*P(S)/Q(S));TANGUTS	LDA #F_TANQ	; Tan Q coefs, P immed after	JSR T2POVERQ	; X <-- T^2*P/Q;; Compute T^5*P/Q, common to both formulas.;	LDX #F_Z	; Z = T^3	JSR KLUGE21;; Compare T*T with 1/4 to decide which formula to continue.;	LDX #F_W	; W = T*T	LDY #F_FPKFOURTH	; 1/4	JSR KLUGE28	FBGT TGBIG;; Using first, simpler formula.;	LDX #F_FPK3	; 3	LDY #F_Z	; Z = T^3	JSR KLUGE93	LDX #F_Z	; Z	LDY #F_X	; X	JSR KLUGE98	LDX #F_X	JMP KLUGE97	; = TGFIN, Go add to T and exit;; Using more complicated formula.;TGBIG	JSR KLUGE51	; Y <-- T	LDX #F_FPK34	; 3/4	LDY #F_Y	; Y	JSR KLUGE91	LDX #F_FPK3	; 3	LDY #F_Y	; Y	JSR KLUGE93	LDX #F_W	; W = T*T	LDY #F_Y	; Y = T'	JSR KLUGE25	LDX #F_X	; X = T^5*P/Q	LDY #F_Y	; Y	JSR KLUGE98	LDX #F_FPKFOURTH	; 1/4	JSR KLUGE24	LDX #F_W	; W	LDY #F_Y	; Y	JSR KLUGE98	LDX #F_Y	; Set up for last add...TGFIN	JMP KLUGE97; Finish off tangent, adding (A0_addr) into T in Result.;;; Arctan (T) for any  -INF  <= T <= INF.; Input:  DEST	 = operand T;         SRC2_CLASS = class (-4..1) for DEST; Output: DEST	 = result; Uses:   A0_ADDR -	A2-ADDR, OP1_ADDR;         Cells:  W_TEMP, X_TEMP, Y_TEMP, Z_TEMP, SRC (as a	temporary),;                 D2_TEMP;; About the argument reduction:  ATAN (T) is evaluated for 0 <= T <= 1.; Recall the identities:;    atan (T)	         = atan (T);    atan (-T)	         = -atan (T);    atan (1/T)	         = pi/2 - atan (T); If T < 0 then atan (-T) is computed, and the result negated.; To compute atan of reduced T use formulas:;      T <= ATnCons	 = 0.267...   T  -	T * P(T*T) / Q(T*T);      else	              T  -	(A  +  (B*P(B*B) / Q(B*B) + x2fx2));               where  x2 and x2fx2 are	constants, about 0.5 and 0.05, and;               A =	(T - x2)/(1 + (1/(T*x2))), and;               B =	(T - x2)/(1 +    (T*x2)).;	EXPORT ATANTOPATANTOP		;       	LDA <SRC2_CLASS	CMP #FCZERO	BPL ATFINITE	; 0, norm, or denorm	LDX #F_FPKPI2	JSR KLUGE8;		        ; Infinite case	LDA <SRC2_SIGN	; Force sign of result	BPL z5s01	JSR KLUGE62Z5S01	JMP ATQUICKATFINITE	BNE ATHARD	; Zero if result is	zeroATQUICK	JMP RESULTDELIVEREDATHARD	JSR KLUGE63	JSR ATANGUTS	LDA <SRC2_SIGN	; Replace sign of ATAN	BPL z6s01	; Better to just take abs.?	JSR KLUGE62Z6S01	JMP TRIGFINI;; Use D2_TEMP to store Boolean about whether input T was inverted in order; to obtain an argument no bigger than one.;ATANGUTS	LDA #$0	STA <D2_TEMP	; Set to false	LDX #F_DEST	; T	LDY #F_FPK1	; 1	JSR KLUGE28	FBLE AGNOINV	LDA #$1	; Set to true	STA <D2_TEMP	JSR KLUGE34;; Store a copy of reduced T on stack for later.;AGNOINV	LDX #F_DEST	; SRC <-- copy of DEST	LDY #F_SRC	JSR MOVEIT;; Select short or long form based on Result vs. ATnCons, about 0.268.;	LDX #F_DEST	; Result	LDY #F_FPKATNCONS	JSR KLUGE28	FBGT AGLONGFORM	; Compare as Res - ATnCons;; Short form.;;               ;MOVE            C_ATANQ,A1_ADDR;		        ; Double check to see if;		        ; OP1 is the correct zero;		        ; p loc	LDA #F_ATANQ	JSR POVERQ	; X <-- P(T*T)/Q(T*T)	JSR KLUGE19	JMP AGFINIKLUGE34	JSR KLUGE42	LDX #F_FPK1	JSR KLUGE8	JSR KLUGE95	RTS;; Long form.;AGLONGFORM	JSR KLUGE42	LDX #F_FPKX2	; X2	JSR KLUGE24	LDX #F_FPK1	; Y <-- 1	JSR KLUGE52	LDX #F_W	; W = T*X2	LDY #F_Y	; Y = 1	JSR KLUGE93	LDX #F_FPK1	; 1	LDY #F_Y	; Y = 1/(T*X2)	JSR KLUGE98	LDX #F_FPK1	; 1	LDY #F_W	; W = T*X2	JSR KLUGE98	LDX #F_FPKX2	; Constant x2	JSR KLUGE90	LDX #F_DEST	; Z <-- T-x2	JSR KLUGE48	JSR KLUGE95	; = B	LDX #F_Y	; Y = 1 + 1/(T*x2)	LDY #F_Z	; Z = T-x2	JSR KLUGE93	; = A	LDA #F_ATANQ	JSR POVERQ	; X <-- P(B*B)/Q(B*B);		        ; W <-- B*B, unused;		        ; Y <-- junk;		        ; Z   = A, still;		        ; Res = B, still	JSR KLUGE19	LDX #F_FPKX2FX2	; Constant x2fx2	JSR KLUGE97	LDX #F_Z	; Z = A	JSR KLUGE97;; Finish up by computing:;       no inversion above:  T - Result	 in Result;       inversion above:     pi/2 - (T - Result)  in Result; Remember that T was saved in SRC eariler.;AGFINI	LDX #F_SRC	; Saved T	JSR KLUGE90	LDA <D2_TEMP	; Nonzero if inverted	BNE AGSUBPI2	JMP KLUGE62AGSUBPI2	LDX #F_FPKPI2	; PI/2	JMP KLUGE97;; Random number generator.  Adapted from "A More Portable FORTRAN Random; Number Generator," Linus Schrage, ACM	Transactions on Mathematical; Software, Vol. 5,	No. 2, June 1979, pp. 132-138.;; NextT  <--  ARand	* T + PRand;      where  ARand	= 7^5  and  PRand =	2^31-1; X is presumed to be an integer strictly between 0 and 2^31-1.; Input:  DEST  = T; Ouput:  DEST  = NextT;	EXPORT RANDTOPRANDTOP		;       	LDX #F_FPKARAND	JSR KLUGE20	LDX #F_FPKPRAND	JSR KLUGE99	JSR KLUGE61	BPL z7s01	; done if result positive	LDX #F_FPKPRAND	;   else add 2^31-1	JSR KLUGE97Z7S01	JMP RESULTDELIVERED	LONGA ON	LONGI ON	ENDP;; END OF FILE;;; END OF FILE;;	END